dotnetSource "LawSpec.Runtime/Codecs.fs" = "/// Conversions between portable values and the native .NET types adapters\n/// use. The generated code composes these for each adapter's signature, and\n/// generates one for each data type, so no reflection is involved.\n/// ref:DEC-typed-core-boundary ref:DEC-native-bindings-typed-identity\nnamespace LawSpec.Runtime\n\nopen System\nopen System.Numerics\nopen System.Text\nopen LawSpec\n\n/// To and from a native type.\ntype Codec<'T> =\n    { ToNative: Value -> 'T\n      FromNative: 'T -> Value }\n\nmodule Codec =\n    let private wrong (expected: string) (value: Value) : 'a =\n        Fail.raiseWith \"InvalidNativeValue\" (sprintf \"expected %s, got %A\" expected value)\n\n    let private integer name (value: Value) =\n        match value with\n        | Int n -> n\n        | _ -> wrong name value\n\n    let inline private bounded name (convert: BigInteger -> 'T) (back: 'T -> BigInteger) : Codec<'T> =\n        { ToNative = fun v -> convert (integer name v)\n          FromNative = fun n -> Int(back n) }\n\n    [<CompiledName(\"Int8\")>]\n    let int8 = bounded \"Int8\" sbyte BigInteger\n    [<CompiledName(\"Int16\")>]\n    let int16 = bounded \"Int16\" int16 BigInteger\n    [<CompiledName(\"Int32\")>]\n    let int32 = bounded \"Int32\" int32 (fun (n: int) -> BigInteger n)\n    [<CompiledName(\"Int64\")>]\n    let int64 = bounded \"Int64\" int64 (fun (n: int64) -> BigInteger n)\n    [<CompiledName(\"UInt8\")>]\n    let uint8 = bounded \"UInt8\" byte BigInteger\n    [<CompiledName(\"UInt16\")>]\n    let uint16 = bounded \"UInt16\" uint16 BigInteger\n    [<CompiledName(\"UInt32\")>]\n    let uint32 = bounded \"UInt32\" uint32 (fun (n: uint32) -> BigInteger n)\n    [<CompiledName(\"UInt64\")>]\n    let uint64 = bounded \"UInt64\" uint64 (fun (n: uint64) -> BigInteger n)\n    [<CompiledName(\"BigInteger\")>]\n    let bigint: Codec<BigInteger> = { ToNative = integer \"Integer\"; FromNative = Int }\n\n    [<CompiledName(\"Bool\")>]\n    let bool: Codec<bool> =\n        { ToNative = (function Bool b -> b | v -> wrong \"Bool\" v)\n          FromNative = Bool }\n\n    [<CompiledName(\"Unit\")>]\n    let unit: Codec<unit> =\n        { ToNative = (function Unit -> () | v -> wrong \"Unit\" v)\n          FromNative = fun () -> Unit }\n\n    [<CompiledName(\"Null\")>]\n    let nullValue: Codec<Null> =\n        { ToNative = (function Value.Null -> Null.Null | v -> wrong \"Null\" v)\n          FromNative = fun _ -> Value.Null }\n\n    [<CompiledName(\"Undefined\")>]\n    let undefinedValue: Codec<Undefined> =\n        { ToNative = (function Value.Undefined -> Undefined.Undefined | v -> wrong \"Undefined\" v)\n          FromNative = fun _ -> Value.Undefined }\n\n    [<CompiledName(\"Text\")>]\n    let text: Codec<string> =\n        { ToNative = (function Text s -> s | v -> wrong \"Text\" v)\n          FromNative = fun s ->\n              if isNull s then Fail.raiseWith \"InvalidNativeValue\" \"a null string\"\n              Text s }\n\n    /// Bytes cross as a copy, so neither side can change the other's.\n    [<CompiledName(\"Bytes\")>]\n    let bytes: Codec<byte[]> =\n        { ToNative = (function Bytes b -> Array.copy b | v -> wrong \"Bytes\" v)\n          FromNative = fun b ->\n              if isNull b then Fail.raiseWith \"InvalidNativeValue\" \"a null byte array\"\n              Bytes(Array.copy b) }\n\n    [<CompiledName(\"Char\")>]\n    let rune: Codec<Rune> =\n        { ToNative = fun v -> Rune(int (integer \"Char\" v))\n          FromNative = fun r -> Int(BigInteger r.Value) }\n\n    [<CompiledName(\"CodePoint\")>]\n    let codePoint: Codec<int> = bounded \"CodePoint\" int (fun (n: int) -> BigInteger n)\n\n    [<CompiledName(\"CodeUnit16\")>]\n    let codeUnit16: Codec<char> = bounded \"CodeUnit16\" (fun n -> char (int n)) (fun (c: char) -> BigInteger(int c))\n\n    [<CompiledName(\"CodePointText\")>]\n    let codePointText: Codec<int list> =\n        { ToNative = (function Raw(_, units) -> units | v -> wrong \"CodePointText\" v)\n          FromNative = fun units -> Raw(\"CodePointText\", units) }\n\n    [<CompiledName(\"Utf16Text\")>]\n    let utf16Text: Codec<string> =\n        { ToNative = (function Raw(_, units) -> String(units |> List.map char |> Array.ofList) | v -> wrong \"Utf16Text\" v)\n          FromNative = fun s -> Raw(\"Utf16Text\", s |> Seq.map int |> List.ofSeq) }\n\n    [<CompiledName(\"Float32\")>]\n    let float32: Codec<float32> =\n        { ToNative = (function Float(32, b) -> BitConverter.UInt32BitsToSingle(Operators.uint32 b) | v -> wrong \"Float32\" v)\n          FromNative = Scalar.floatFromSingle }\n\n    [<CompiledName(\"Float64\")>]\n    let float64: Codec<float> =\n        { ToNative = (function Float(64, b) -> BitConverter.UInt64BitsToDouble b | v -> wrong \"Float64\" v)\n          FromNative = Scalar.floatFromDouble }\n\n    [<CompiledName(\"Complex64\")>]\n    let complex64: Codec<Complex64> =\n        { ToNative = (function Complex(_, r, i) -> { Real = float32.ToNative r; Imaginary = float32.ToNative i } | v -> wrong \"Complex64\" v)\n          FromNative = fun c -> Value.Complex(32, float32.FromNative c.Real, float32.FromNative c.Imaginary) }\n\n    [<CompiledName(\"Complex128\")>]\n    let complex128: Codec<Complex> =\n        { ToNative = (function Complex(_, r, i) -> Complex(float64.ToNative r, float64.ToNative i) | v -> wrong \"Complex128\" v)\n          FromNative = fun c -> Value.Complex(64, float64.FromNative c.Real, float64.FromNative c.Imaginary) }\n\n    [<CompiledName(\"Rational\")>]\n    let rational: Codec<Rational> =\n        { ToNative = (function Ratio(n, d) -> Rational.Create(n, d) | v -> wrong \"Rational\" v)\n          FromNative = fun r -> Scalar.ratio r.Numerator r.Denominator }\n\n    [<CompiledName(\"Decimal\")>]\n    let exactDecimal: Codec<ExactDecimal> =\n        { ToNative = (function Decimal(c, e) -> { Coefficient = c; Exponent = e } | v -> wrong \"Decimal\" v)\n          FromNative = fun d -> Value.Decimal(d.Coefficient, d.Exponent) }\n\n    [<CompiledName(\"Symbol\")>]\n    let symbol: Codec<Symbol> =\n        { ToNative = (function Value.Symbol(id, d) -> Symbol(id, d) | v -> wrong \"Symbol\" v)\n          FromNative = fun s ->\n              if isNull s then Fail.raiseWith \"InvalidNativeValue\" \"a null symbol\"\n              Value.Symbol(s.Identity, s.Description) }\n\n    [<CompiledName(\"List\")>]\n    let list (item: Codec<'T>) : Codec<'T list> =\n        { ToNative = (function List items -> items |> List.map item.ToNative | v -> wrong \"List\" v)\n          FromNative = fun items -> List(items |> List.map item.FromNative) }\n\n    [<CompiledName(\"Maybe\")>]\n    let option (item: Codec<'T>) : Codec<'T option> =\n        { ToNative =\n            (function\n            | Data(\"Maybe::Nothing\", []) -> None\n            | Data(\"Maybe::Just\", [ v ]) -> Some(item.ToNative v)\n            | v -> wrong \"Maybe\" v)\n          FromNative =\n            (function\n            | None -> Data(\"Maybe::Nothing\", [])\n            | Some v -> Data(\"Maybe::Just\", [ item.FromNative v ])) }\n\n    [<CompiledName(\"Either\")>]\n    let either (left: Codec<'L>) (right: Codec<'R>) : Codec<Either<'L, 'R>> =\n        { ToNative =\n            (function\n            | Data(\"Either::Left\", [ v ]) -> Either.Left(left.ToNative v)\n            | Data(\"Either::Right\", [ v ]) -> Either.Right(right.ToNative v)\n            | v -> wrong \"Either\" v)\n          FromNative =\n            (function\n            | Either.Left v -> Data(\"Either::Left\", [ left.FromNative v ])\n            | Either.Right v -> Data(\"Either::Right\", [ right.FromNative v ])) }\n\n    [<CompiledName(\"Nullable\")>]\n    let nullable (item: Codec<'T>) : Codec<Nullable<'T>> =\n        { ToNative =\n            (function\n            | Presence(_, None) -> Nullable.Null\n            | Presence(_, Some v) -> Nullable.Present(item.ToNative v)\n            | v -> wrong \"Nullable\" v)\n          FromNative =\n            (function\n            | Nullable.Null -> Presence(\"Nullable\", None)\n            | Nullable.Present v -> Presence(\"Nullable\", Some(item.FromNative v))) }\n\n    [<CompiledName(\"Optional\")>]\n    let optional (item: Codec<'T>) : Codec<Optional<'T>> =\n        { ToNative =\n            (function\n            | Presence(_, None) -> Optional.Undefined\n            | Presence(_, Some v) -> Optional.Present(item.ToNative v)\n            | v -> wrong \"Optional\" v)\n          FromNative =\n            (function\n            | Optional.Undefined -> Presence(\"Optional\", None)\n            | Optional.Present v -> Presence(\"Optional\", Some(item.FromNative v))) }\n\n    /// A handle's identity crosses unchanged.\n    [<CompiledName(\"Handle\")>]\n    let handle<'T when 'T: not struct> (name: string) : Codec<'T> =\n        { ToNative = (function Handle(_, identity) -> unbox<'T> identity | v -> wrong name v)\n          FromNative = fun native ->\n              if isNull (box native) then Fail.raiseWith \"HandleRequiresIdentity\" name\n              Handle(name, box native) }\n\n    /// The value itself, for a type with no native form.\n    [<CompiledName(\"Portable\")>]\n    let portable: Codec<Value> = { ToNative = id; FromNative = id }\n"
dotnetSource "LawSpec.Runtime/LawSpec.Runtime.fsproj" = "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <!-- Generated by LawSpec. Do not edit. The LawSpec runtime for F# and C#. -->\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n    <Nullable>disable</Nullable>\n    <TreatWarningsAsErrors>true</TreatWarningsAsErrors>\n    <GenerateDocumentationFile>false</GenerateDocumentationFile>\n    <IsPackable>false</IsPackable>\n  </PropertyGroup>\n  <ItemGroup>\n    <Compile Include=\"Values.fs\" />\n    <Compile Include=\"Native.fs\" />\n    <Compile Include=\"Scalar.fs\" />\n    <Compile Include=\"Regex.fs\" />\n    <Compile Include=\"Random.fs\" />\n    <Compile Include=\"Schema.fs\" />\n    <Compile Include=\"Recorded.fs\" />\n    <Compile Include=\"Portable.fs\" />\n    <Compile Include=\"Codecs.fs\" />\n    <Compile Include=\"Runtime.fs\" />\n  </ItemGroup>\n</Project>\n"
dotnetSource "LawSpec.Runtime/Native.fs" = "/// The .NET types LawSpec values take at the native boundary, where a .NET\n/// type has no exact counterpart: exact fractions and decimals, single\n/// precision complex numbers, the two kinds of presence, and symbols. Every\n/// other LawSpec type maps to a .NET type directly (sbyte ... uint64, bigint,\n/// string, byte[], list, option, Rune). ref:DEC-fsharp-runtime-from-scratch\nnamespace LawSpec\n\nopen System.Numerics\n\n/// An exact fraction in lowest terms, with a positive denominator.\n[<CustomEquality; CustomComparison>]\ntype Rational =\n    private { N: BigInteger; D: BigInteger }\n    member this.Numerator = this.N\n    member this.Denominator = this.D\n    static member Create(numerator: BigInteger, denominator: BigInteger) =\n        if denominator.IsZero then invalidArg (nameof denominator) \"a rational's denominator is not zero\"\n        let g = BigInteger.GreatestCommonDivisor(numerator, denominator)\n        let s = if denominator.Sign < 0 then BigInteger.MinusOne else BigInteger.One\n        { N = s * numerator / g; D = BigInteger.Abs denominator / g }\n    override this.Equals other =\n        match other with\n        | :? Rational as r -> this.N = r.N && this.D = r.D\n        | _ -> false\n    override this.GetHashCode() = hash (this.N, this.D)\n    override this.ToString() = sprintf \"%O/%O\" this.N this.D\n    interface System.IComparable with\n        member this.CompareTo other =\n            match other with\n            | :? Rational as r -> compare (this.N * r.D) (r.N * this.D)\n            | _ -> invalidArg \"other\" \"a rational compares with a rational\"\n\n/// coefficient * 10 ^ exponent, exactly; 1.50 keeps its two places.\n[<Struct; CustomEquality; NoComparison>]\ntype ExactDecimal =\n    { Coefficient: BigInteger\n      Exponent: int }\n    override this.Equals other =\n        match other with\n        | :? ExactDecimal as d -> this.Coefficient = d.Coefficient && this.Exponent = d.Exponent\n        | _ -> false\n    override this.GetHashCode() = hash (this.Coefficient, this.Exponent)\n    override this.ToString() = sprintf \"%Oe%d\" this.Coefficient this.Exponent\n    /// Both decimals at the smaller exponent.\n    static member private Aligned(a: ExactDecimal, b: ExactDecimal) =\n        let e = min a.Exponent b.Exponent\n        let scale (d: ExactDecimal) = d.Coefficient * BigInteger.Pow(BigInteger 10, d.Exponent - e)\n        scale a, scale b, e\n    /// Exact sum, at the finer of the two scales.\n    static member (+)(a: ExactDecimal, b: ExactDecimal) =\n        let x, y, e = ExactDecimal.Aligned(a, b)\n        { Coefficient = x + y; Exponent = e }\n    /// Exact difference, at the finer of the two scales.\n    static member (-)(a: ExactDecimal, b: ExactDecimal) =\n        let x, y, e = ExactDecimal.Aligned(a, b)\n        { Coefficient = x - y; Exponent = e }\n    /// Exact product.\n    static member (*)(a: ExactDecimal, b: ExactDecimal) =\n        { Coefficient = a.Coefficient * b.Coefficient; Exponent = a.Exponent + b.Exponent }\n\n/// A complex number of two single precision floats (Complex128 is\n/// System.Numerics.Complex).\n[<Struct>]\ntype Complex64 = { Real: float32; Imaginary: float32 }\n\n/// A value that may be null, distinct from an absent Optional.\n[<RequireQualifiedAccess>]\ntype Nullable<'T> =\n    | Null\n    | Present of 'T\n\n/// A value that may be undefined, distinct from a null Nullable.\n[<RequireQualifiedAccess>]\ntype Optional<'T> =\n    | Undefined\n    | Present of 'T\n\n/// Either of two values; Left conventionally the failure.\n[<RequireQualifiedAccess>]\ntype Either<'L, 'R> =\n    | Left of left: 'L\n    | Right of right: 'R\n\n/// LawSpec's Null value.\ntype Null = | Null\n\n/// LawSpec's Undefined value.\ntype Undefined = | Undefined\n\n/// A symbol: equal only to itself.\n[<Sealed; AllowNullLiteral>]\ntype Symbol(identity: obj, description: string) =\n    new(description) = Symbol(obj (), description)\n    member _.Identity = identity\n    member _.Description = description\n    override _.Equals other =\n        match other with\n        | :? Symbol as s -> obj.ReferenceEquals(identity, s.Identity)\n        | _ -> false\n    override _.GetHashCode() = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode identity\n    override _.ToString() = \"Symbol(\" + description + \")\"\n"
dotnetSource "LawSpec.Runtime/Portable.fs" = "/// LawSpec's portable equality, hash and order over native .NET values. The\n/// generated records and unions use it, so a native value orders as its\n/// portable value does on every target: text by code point, constructors by\n/// their identities, fields left to right. ref:DEC-portable-exact-arithmetic\n/// ref:DEC-idiomatic-generated-types\nmodule LawSpec.Runtime.Portable\n\nopen System\nopen System.Collections\nopen System.Numerics\nopen System.Text\nopen LawSpec\n\nlet private noOrder (a: obj) = Fail.raiseWith \"NoPortableOrder\" (if isNull a then \"null\" else a.GetType().Name)\n\n/// Equality: structural, with floats compared by their bits (so it is\n/// reflexive, as .NET collections require).\n[<CompiledName(\"Equal\")>]\nlet rec equal (a: obj) (b: obj) : bool =\n    match a, b with\n    | null, null -> true\n    | null, _ | _, null -> false\n    | (:? float as x), (:? float as y) -> BitConverter.DoubleToInt64Bits x = BitConverter.DoubleToInt64Bits y\n    | (:? float32 as x), (:? float32 as y) -> BitConverter.SingleToInt32Bits x = BitConverter.SingleToInt32Bits y\n    | (:? string as x), (:? string as y) -> String.Equals(x, y, StringComparison.Ordinal)\n    | (:? (byte[]) as x), (:? (byte[]) as y) -> ReadOnlySpan<byte>(x).SequenceEqual(ReadOnlySpan<byte>(y))\n    | (:? IStructuralEquatable as x), _ when not (a :? string) -> x.Equals(b, StructuralComparisons.StructuralEqualityComparer)\n    | _ -> a.Equals b\n\n/// A hash consistent with equal.\n[<CompiledName(\"Hash\")>]\nlet rec hash (a: obj) : int =\n    match a with\n    | null -> 0\n    | :? float as x -> BitConverter.DoubleToInt64Bits(x).GetHashCode()\n    | :? float32 as x -> BitConverter.SingleToInt32Bits(x)\n    | :? (byte[]) as x ->\n        let mutable h = 17\n        for b in x do h <- h * 31 + int b\n        h\n    | :? IStructuralEquatable as x -> x.GetHashCode(StructuralComparisons.StructuralEqualityComparer)\n    | _ -> a.GetHashCode()\n\n/// Generated records and unions implement this: their CompareTo is the\n/// portable order.\ntype IPortable =\n    inherit IComparable\n\nlet private unionCache = Collections.Concurrent.ConcurrentDictionary<Type, (obj -> int) * (obj -> obj[])>()\n\nlet private unionParts (t: Type) =\n    unionCache.GetOrAdd(t, fun t ->\n        let tag = Reflection.FSharpValue.PreComputeUnionTagReader(t)\n        let readers =\n            Reflection.FSharpType.GetUnionCases(t)\n            |> Array.map (fun c -> Reflection.FSharpValue.PreComputeUnionReader(c))\n        tag, (fun v -> readers.[tag v] v))\n\n/// The portable order of two native values of one type.\n[<CompiledName(\"Compare\")>]\nlet rec compare (a: obj) (b: obj) : int =\n    match a, b with\n    | null, null -> 0\n    | null, _ -> -1\n    | _, null -> 1\n    | (:? string as x), (:? string as y) -> Scalar.compareText x y\n    | (:? (byte[]) as x), (:? (byte[]) as y) -> Scalar.compareBytes x y\n    | (:? bool as x), (:? bool as y) -> Operators.compare x y\n    | (:? BigInteger as x), (:? BigInteger as y) -> sign (BigInteger.Compare(x, y))\n    | (:? Rune as x), (:? Rune as y) -> Operators.compare x.Value y.Value\n    | (:? float as x), _ -> noOrder x\n    | (:? float32 as x), _ -> noOrder x\n    | (:? Symbol as x), _ -> noOrder x\n    | (:? IPortable as x), _ -> sign (x.CompareTo b)\n    | (:? IComparable as x), _ when a.GetType().IsPrimitive -> sign (x.CompareTo b)\n    | _ when Reflection.FSharpType.IsUnion(a.GetType()) && not (a :? IEnumerable) ->\n        let tag, fields = unionParts (a.GetType())\n        let ta, tb = tag a, tag b\n        if ta <> tb then Operators.compare ta tb\n        else compareSequence (fields a :> IEnumerable) (fields b :> IEnumerable)\n    | (:? IEnumerable as xs), (:? IEnumerable as ys) -> compareSequence xs ys\n    | (:? IComparable as x), _ -> sign (x.CompareTo b)\n    | _ -> noOrder a\n\nand private compareSequence (xs: IEnumerable) (ys: IEnumerable) =\n    let ys = ys.GetEnumerator()\n    let xs = xs.GetEnumerator()\n    let mutable result = None\n    while result.IsNone do\n        match xs.MoveNext(), ys.MoveNext() with\n        | false, false -> result <- Some 0\n        | false, true -> result <- Some -1\n        | true, false -> result <- Some 1\n        | true, true ->\n            match compare xs.Current ys.Current with\n            | 0 -> ()\n            | c -> result <- Some c\n    result.Value\n\n/// Compare two constructors' ranks and then their fields.\n[<CompiledName(\"CompareData\")>]\nlet compareData (rankA: int) (fieldsA: obj list) (rankB: int) (fieldsB: obj list) =\n    if rankA <> rankB then Operators.compare rankA rankB\n    else\n        let rec go xs ys =\n            match xs, ys with\n            | x :: xs, y :: ys ->\n                match compare x y with\n                | 0 -> go xs ys\n                | c -> c\n            | [], [] -> 0\n            | [], _ -> -1\n            | _, [] -> 1\n        go fieldsA fieldsB\n\n/// Whether two constructors' fields are equal.\n[<CompiledName(\"EqualData\")>]\nlet equalData (rankA: int) (fieldsA: obj list) (rankB: int) (fieldsB: obj list) =\n    rankA = rankB && List.length fieldsA = List.length fieldsB && List.forall2 equal fieldsA fieldsB\n\n/// A hash of a constructor and its fields.\n[<CompiledName(\"HashData\")>]\nlet hashData (rank: int) (fields: obj list) = fields |> List.fold (fun h f -> h * 31 + hash f) (rank + 7)\n"
dotnetSource "LawSpec.Runtime/Random.fs" = "/// The portable SplitMix64 sequence. Its state is passed explicitly, so\n/// concurrent callers never draw from one another's stream, and the same seed\n/// replays the same run on every target. ref:splitmix\n/// ref:DEC-portable-seeded-generation\nmodule LawSpec.Runtime.Random\n\nopen System.Numerics\n\n/// A SplitMix64 state.\n[<Struct>]\ntype Seed = Seed of uint64\n\n/// The state for a seed (any integer, reduced to 64 bits).\n[<CompiledName(\"SeedOf\")>]\nlet seed (n: BigInteger) = Seed(uint64 (n &&& BigInteger(System.UInt64.MaxValue)))\n\n/// The next output and state.\n[<CompiledName(\"Next\")>]\nlet next (Seed state) =\n    let s = state + 0x9e3779b97f4a7c15UL\n    let a = (s ^^^ (s >>> 30)) * 0xbf58476d1ce4e5b9UL\n    let b = (a ^^^ (a >>> 27)) * 0x94d049bb133111ebUL\n    b ^^^ (b >>> 31), Seed s\n\n/// A draw below a bound (0 for a bound that is not positive), as every\n/// runtime reduces it: the output modulo the bound.\n[<CompiledName(\"Below\")>]\nlet below (bound: BigInteger) (state: Seed) =\n    if bound.Sign <= 0 then BigInteger.Zero, state\n    else\n        let n, next' = next state\n        BigInteger.Remainder(BigInteger n, bound), next'\n\n/// Two independent states from one, for generators that branch.\n[<CompiledName(\"Split\")>]\nlet split (state: Seed) =\n    let a, s1 = next state\n    let b, _ = next s1\n    Seed a, Seed b\n"
dotnetSource "LawSpec.Runtime/Recorded.fs" = "/// Typed text for recorded values. Every target writes a recording the same\n/// way, so one recorded file checks every implementation. Identities (symbols\n/// and handles) are numbered within one recording. ref:REQ-law-primitives\n/// ref:DEC-portable-exact-arithmetic\nmodule LawSpec.Runtime.Recorded\n\nopen System\nopen System.Numerics\n\nlet private quote (s: string) = \"\\\"\" + s.Replace(\"\\\\\", \"\\\\\\\\\").Replace(\"\\\"\", \"\\\\\\\"\") + \"\\\"\"\n\nlet private lastPart (tag: string) =\n    let parts = tag.Split(\"::\")\n    parts.[parts.Length - 1]\n\nlet rec private trimDecimal (c: BigInteger) e =\n    if c.IsZero then BigInteger.Zero, 0\n    elif (c % BigInteger 10).IsZero then trimDecimal (c / BigInteger 10) (e + 1)\n    else c, e\n\nlet private floatText value =\n    match value with\n    | Float(w, bits) ->\n        let name = \"float\" + string w\n        if Scalar.floatClass value = \"nan\" then name + \"NaN\"\n        else name + \"Bits(\\\"\" + bits.ToString(if w = 32 then \"x8\" else \"x16\") + \"\\\")\"\n    | _ -> Fail.raiseWith \"InvalidRecordedScalar\" \"float\"\n\nlet private units name (values: int seq) =\n    name + \"([\" + String.Join(\", \", values |> Seq.map string) + \"])\"\n\nlet private scalar value (t: string) =\n    match t, value with\n    | \"Bool\", Bool b -> if b then \"true\" else \"false\"\n    | \"Unit\", Unit -> \"()\"\n    | \"Null\", Null -> \"null\"\n    | \"Undefined\", Undefined -> \"undefined\"\n    | \"Text\", Text s -> quote s\n    | \"Char\", Int n -> quote (Text.Rune(int n).ToString())\n    | (\"CodePoint\" | \"CodeUnit16\"), Int n -> n.ToString()\n    | \"Bytes\", Bytes b -> units \"bytes\" (b |> Seq.map int)\n    | \"CodePointText\", Raw(_, us) -> units \"codePoints\" us\n    | \"Utf16Text\", Raw(_, us) -> units \"utf16\" us\n    | \"Decimal\", Decimal(c, e) ->\n        let c, e = trimDecimal c e\n        c.ToString() + \"e\" + string e\n    | \"Rational\", Ratio(n, d) -> \"rational(\" + n.ToString() + \", \" + d.ToString() + \")\"\n    | (\"Float32\" | \"Float64\"), Float _ -> floatText value\n    | \"Complex64\", Complex(_, r, i) -> \"Complex64(\" + floatText r + \", \" + floatText i + \")\"\n    | \"Complex128\", Complex(_, r, i) -> \"Complex128(\" + floatText r + \", \" + floatText i + \")\"\n    | _, Int n when Scalar.isIntegerType t -> n.ToString()\n    | _ -> Fail.raiseWith \"InvalidRecordedScalar\" t\n\ntype private Ids = Map<string, (obj * int) list>\n\nlet private identity kind (value: obj) (ids: Ids) =\n    let known = defaultArg (ids.TryFind kind) []\n    match known |> List.tryFind (fun (v, _) -> Object.ReferenceEquals(v, value) || v.Equals value) with\n    | Some(_, n) -> n, ids\n    | None ->\n        let n = List.length known + 1\n        n, ids.Add(kind, known @ [ value, n ])\n\nlet rec private render (value: Value) (t: TypeRef) (schema: Schema.Schema option) (ids: Ids) : string * Ids =\n    match t, value with\n    | Named(\"List\", [ element ]), List items ->\n        let (parts: string list), next = sequence items (items |> List.map (fun _ -> element)) schema ids\n        \"[\" + String.Join(\", \", parts) + \"]\", next\n    | Named(kind, [ _ ]), Presence(_, None) -> (if kind = \"Nullable\" then \"null\" else \"undefined\"), ids\n    | Named(kind, [ inner ]), Presence(_, Some v) ->\n        let part, next = render v inner schema ids\n        (if kind = \"Nullable\" then \"nullable(\" else \"optional(\") + part + \")\", next\n    | Named(\"Symbol\", []), Symbol(id, description) ->\n        let n, next = identity \"symbol\" id ids\n        \"symbol(\" + string n + \", \" + quote description + \")\", next\n    | Named(name, []), Handle(_, id) ->\n        let n, next = identity (\"handle \" + name) id ids\n        lastPart name + \"#\" + string n, next\n    | _, Data(tag, fields) ->\n        let types =\n            match t, tag with\n            | _, \"Maybe::Nothing\" -> []\n            | Named(\"Maybe\", [ inner ]), _ -> [ inner ]\n            | Named(\"Either\", [ l; _ ]), \"Either::Left\" -> [ l ]\n            | Named(\"Either\", [ _; r ]), \"Either::Right\" -> [ r ]\n            | _ ->\n                match schema with\n                | Some s -> Schema.fieldTypes value t s\n                | None -> Fail.raiseWith \"RecordingNeedsSchema\" tag\n        let (parts: string list), next = sequence fields types schema ids\n        (if List.isEmpty parts then lastPart tag else lastPart tag + \"(\" + String.Join(\", \", parts) + \")\"), next\n    | Named(name, []), _ -> scalar value name, ids\n    | _ -> Fail.raiseWith \"InvalidRecordedValue\" (Scalar.typeKey t)\n\nand private sequence (values: Value list) (types: TypeRef list) schema ids : string list * Ids =\n    List.zip values types\n    |> List.fold (fun (parts, ids) (v, t) ->\n        let part, next = render v t schema ids\n        parts @ [ part ], next) ([], ids)\n\n/// A value's recorded text at its type.\n[<CompiledName(\"Text\")>]\nlet text (value: Value) (t: TypeRef) (schema: Schema.Schema option) = fst (render value t schema Map.empty)\n\n/// The untyped rendering a model's recorded state uses.\n[<CompiledName(\"Render\")>]\nlet rec renderPlain (value: Value) : string =\n    match value with\n    | Bool true -> \"true\"\n    | Bool false -> \"false\"\n    | Unit -> \"()\"\n    | Int n -> n.ToString()\n    | Text s -> quote s\n    | List items -> \"[\" + String.Join(\", \", items |> List.map renderPlain) + \"]\"\n    | Data(tag, []) -> lastPart tag\n    | Data(tag, fields) -> lastPart tag + \"(\" + String.Join(\", \", fields |> List.map renderPlain) + \")\"\n    | _ -> sprintf \"%A\" value\n"
dotnetSource "LawSpec.Runtime/Regex.fs" = "/// LawSpec's portable regex grammar, on Unicode scalar values rather than\n/// .NET's regex engine and its character classes. A match covers the whole\n/// text, and matching tracks reachable positions, so an ambiguous repeat\n/// never backtracks exponentially. ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Regex\n\nopen System.Collections.Concurrent\n\n/// A compiled pattern.\ntype Node =\n    /// A character set: negated, and items each (negated, ranges).\n    | Set of negated: bool * items: (bool * (int * int) list) list\n    | Sequence of Node list\n    | Alternatives of Node list\n    | Repeat of Node * low: int * high: int option\n\nlet private fail reason : 'a = Fail.raiseWith \"NonPortableRegex\" reason\n\nlet private require condition reason = if not condition then fail reason\n\nlet private escape (cs: int list) =\n    match cs with\n    | c :: rest when c = int 'd' || c = int 'D' -> (c = int 'D', [ 48, 57 ]), rest\n    | c :: rest when c = int 'w' || c = int 'W' -> (c = int 'W', [ 48, 57; 65, 90; 95, 95; 97, 122 ]), rest\n    | c :: rest when c = int 's' || c = int 'S' -> (c = int 'S', [ 9, 13; 32, 32 ]), rest\n    | c :: rest ->\n        let named = [ int 'n', 10; int 't', 9; int 'r', 13; int 'f', 12; int 'v', 11 ]\n        match List.tryFind (fun (k, _) -> k = c) named with\n        | Some(_, v) -> (false, [ v, v ]), rest\n        | None ->\n            require (\"\\\\.^$|?*+()[]{}-/\" |> Seq.exists (fun x -> int x = c)) \"UnsupportedEscape\"\n            (false, [ c, c ]), rest\n    | [] -> fail \"TrailingEscape\"\n\nlet private classItem cs =\n    match cs with\n    | c :: rest when c = int '\\\\' -> escape rest\n    | c :: _ when c = int '[' -> fail \"UnescapedClassOpen\"\n    | c :: rest -> (false, [ c, c ]), rest\n    | [] -> fail \"UnclosedClass\"\n\nlet rec private charClass cs negated acc =\n    match cs with\n    | [] -> fail \"UnclosedClass\"\n    | c :: _ when c = int ']' && List.isEmpty acc -> fail \"EmptyClass\"\n    | c :: rest when c = int ']' -> Set(negated, List.rev acc), rest\n    | _ ->\n        let item, rest = classItem cs\n        match item, rest with\n        | (false, [ lo, lo' ]), dash :: c :: tail when lo = lo' && dash = int '-' && c <> int ']' ->\n            match classItem (c :: tail) with\n            | (false, [ hi, hi' ]), next when hi = hi' && hi >= lo -> charClass next negated ((false, [ lo, hi ]) :: acc)\n            | _ -> fail \"InvalidClassRange\"\n        | _ -> charClass rest negated (item :: acc)\n\nlet private count cs =\n    let digits = cs |> List.takeWhile (fun c -> c >= int '0' && c <= int '9')\n    require (not (List.isEmpty digits)) \"MissingRepetitionCount\"\n    let value = digits |> List.fold (fun n d -> n * 10 + (d - int '0')) 0\n    value, List.skip digits.Length cs\n\nlet private repeat node low high cs =\n    require (low <= 1000 && (match high with None -> true | Some h -> h <= 1000 && h >= low)) \"InvalidRepetitionCount\"\n    match cs with\n    | c :: _ -> require (not (\"*+?{\" |> Seq.exists (fun x -> int x = c))) \"RepeatedQuantifier\"\n    | [] -> ()\n    Repeat(node, low, high), cs\n\nlet private quantified node cs =\n    match cs with\n    | c :: rest when c = int '*' -> repeat node 0 None rest\n    | c :: rest when c = int '+' -> repeat node 1 None rest\n    | c :: rest when c = int '?' -> repeat node 0 (Some 1) rest\n    | c :: rest when c = int '{' ->\n        let low, after = count rest\n        match after with\n        | c :: next when c = int '}' -> repeat node low (Some low) next\n        | c :: d :: next when c = int ',' && d = int '}' -> repeat node low None next\n        | c :: tail when c = int ',' ->\n            let high, after = count tail\n            match after with\n            | d :: next when d = int '}' -> repeat node low (Some high) next\n            | _ -> fail \"UnclosedRepetition\"\n        | _ -> fail \"InvalidRepetition\"\n    | _ -> node, cs\n\nlet rec private alternatives cs =\n    let branch, rest = sequence cs []\n    let rec more rest acc =\n        match rest with\n        | c :: tail when c = int '|' ->\n            let next, after = sequence tail []\n            more after (next :: acc)\n        | _ ->\n            match acc with\n            | [ only ] -> only, rest\n            | _ -> Alternatives(List.rev acc), rest\n    more rest [ branch ]\n\nand private sequence cs acc =\n    match cs with\n    | [] -> Sequence(List.rev acc), []\n    | c :: _ when c = int ')' || c = int '|' -> Sequence(List.rev acc), cs\n    | _ ->\n        let atom, rest = atom cs\n        let node, next = quantified atom rest\n        sequence next (node :: acc)\n\nand private atom cs =\n    match cs with\n    | o :: q :: c :: rest when o = int '(' && q = int '?' && c = int ':' -> group rest\n    | o :: q :: _ when o = int '(' && q = int '?' -> fail \"UnsupportedGroup\"\n    | o :: rest when o = int '(' -> group rest\n    | o :: n :: rest when o = int '[' && n = int '^' -> charClass rest true []\n    | o :: rest when o = int '[' -> charClass rest false []\n    | d :: rest when d = int '.' -> Set(true, [ false, [ 10, 10 ] ]), rest\n    | b :: rest when b = int '\\\\' ->\n        let item, after = escape rest\n        Set(false, [ item ]), after\n    | c :: rest ->\n        require (not (\"*+?{^$]}\" |> Seq.exists (fun x -> int x = c))) \"UnexpectedCharacter\"\n        Set(false, [ false, [ c, c ] ]), rest\n    | [] -> fail \"MissingAtom\"\n\nand private group cs =\n    let node, rest = alternatives cs\n    match rest with\n    | c :: next when c = int ')' -> node, next\n    | _ -> fail \"UnclosedGroup\"\n\nlet private cache = ConcurrentDictionary<string, Node>()\n\n/// Compile a pattern once; compiled patterns are shared.\nlet compile (pattern: string) =\n    cache.GetOrAdd(pattern, fun pattern ->\n        if not (Scalar.isWellFormed pattern) then Fail.raiseWith \"InvalidUnicode\" \"\"\n        let node, rest = alternatives (Scalar.codePoints pattern)\n        require (List.isEmpty rest) \"UnmatchedClosingParenthesis\"\n        node)\n\nlet private inSet (c: int) items =\n    items |> List.exists (fun (negated, ranges) -> negated <> (ranges |> List.exists (fun (lo, hi) -> c >= lo && c <= hi)))\n\nlet rec private reach node (text: int[]) (positions: Set<int>) : Set<int> =\n    match node with\n    | Set(negated, items) ->\n        positions\n        |> Seq.filter (fun p -> p < text.Length && inSet text.[p] items <> negated)\n        |> Seq.map (fun p -> p + 1)\n        |> Set.ofSeq\n    | Sequence nodes -> nodes |> List.fold (fun ps n -> reach n text ps) positions\n    | Alternatives nodes -> nodes |> List.map (fun n -> reach n text positions) |> Set.unionMany\n    | Repeat(inner, low, high) ->\n        let mutable required = positions\n        let mutable i = 0\n        while i < low && not required.IsEmpty do\n            required <- reach inner text required\n            i <- i + 1\n        let mutable seen = required\n        let mutable frontier = required\n        let mutable remaining = high |> Option.map (fun h -> h - low)\n        while not frontier.IsEmpty && remaining <> Some 0 do\n            let next = Set.difference (reach inner text frontier) seen\n            seen <- Set.union seen next\n            frontier <- next\n            remaining <- remaining |> Option.map (fun r -> r - 1)\n        seen\n\n/// Whether a compiled pattern matches the whole text.\nlet run (node: Node) (text: string) =\n    let points = Scalar.codePoints text |> Array.ofList\n    reach node points (Set.singleton 0) |> Set.contains points.Length\n\n/// Whether a pattern matches the whole text.\n[<CompiledName(\"Matches\")>]\nlet matches (pattern: string) (text: string) = run (compile pattern) text\n"
dotnetSource "LawSpec.Runtime/Runtime.fs" = "/// Services the generated definitions and laws share: contracts, equations,\n/// helpers, recordings and concurrent groups. Values stay portable until a\n/// native boundary. ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Runtime\n\nopen System\nopen System.IO\nopen System.Threading.Tasks\n\n/// A portable boolean as a .NET one.\n[<CompiledName(\"Truth\")>]\nlet truth (value: Value) =\n    match value with\n    | Bool b -> b\n    | _ -> Fail.raiseWith \"BoolRequired\" (sprintf \"%A\" value)\n\n[<CompiledName(\"Not\")>]\nlet not (value: Value) = Bool(Operators.not (truth value))\n\n/// The item of a list of values at a position.\n[<CompiledName(\"Item\")>]\nlet item (index: int) (values: Value list) = List.item index values\n\n/// The item of a list at a position.\n[<CompiledName(\"Nth\")>]\nlet nth (index: int) (items: 'a list) = List.item index items\n\n[<CompiledName(\"Some\")>]\nlet some (value: 'a) = Some value\n\n/// A data value's field at a position (a list's head and tail).\n[<CompiledName(\"Field\")>]\nlet field (value: Value) (index: int) =\n    match value, index with\n    | Data(_, fields), _ -> List.item index fields\n    | List(head :: _), 0 -> head\n    | List(_ :: tail), 1 -> List tail\n    | _ -> Fail.raiseWith \"ExpectedData\" (sprintf \"%A\" value)\n\n/// Whether a value was built by a constructor.\n[<CompiledName(\"HasTag\")>]\nlet hasTag (tag: string) (value: Value) =\n    match value with\n    | Data(t, _) -> t = tag\n    | List [] -> tag = \"List::Nil\"\n    | List _ -> tag = \"List::Cons\"\n    | _ -> false\n\n/// A match no branch covers.\n[<CompiledName(\"NoMatch\")>]\nlet noMatch (value: Value) : Value = Fail.raiseWith \"MatchFailure\" (sprintf \"%A\" value)\n\n/// Whether every element of a list satisfies a predicate.\n[<CompiledName(\"AllElements\")>]\nlet allElements (value: Value) (predicate: Value -> Value) =\n    match value with\n    | List items -> Bool(items |> List.forall (predicate >> truth))\n    | _ -> Fail.raiseWith \"ListRequired\" \"\"\n\n/// Whether every payload of a container satisfies its parameter's predicate.\n[<CompiledName(\"AllPayloads\")>]\nlet allPayloads (value: Value) (t: TypeRef) (predicates: (Value -> Value) list) (schema: Schema.Schema) =\n    Bool(Schema.allPayloads value t (predicates |> List.map (fun p -> p >> truth)) schema)\n\n/// Nullable or Optional, absent.\n[<CompiledName(\"Absent\")>]\nlet absent (kind: string) = Presence(kind, None)\n\n/// Nullable or Optional, present.\n[<CompiledName(\"Present\")>]\nlet present (kind: string) (value: Value) = Presence(kind, Some value)\n\n/// Fail a contract unless it holds.\n[<CompiledName(\"Require\")>]\nlet require (holds: Value) (context: string) : unit =\n    match holds with\n    | Bool true -> ()\n    | Bool false -> Fail.raiseWith \"ContractFailed\" context\n    | _ -> Fail.raiseWith \"NonBooleanContract\" context\n\n/// An equation of a law: both sides are kept for the report.\n[<CompiledName(\"AssertEqual\")>]\nlet assertEqual (actual: Value) (expected: Value) (label: string) : Value =\n    if Scalar.equal actual expected then Bool true\n    else Fail.raiseWith \"EquationFailed\" (sprintf \"%s: actual %s, expected %s\" label (Recorded.renderPlain actual) (Recorded.renderPlain expected))\n\n/// Name the definition or law a LawSpec failure happened in.\n[<CompiledName(\"Contextual\")>]\nlet contextual (identity: string) (body: unit -> 'a) : 'a =\n    try body () with\n    | :? LawSpecException as e -> raise (e.Within identity)\n\nlet private recordedRoot () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_RECORDED\" with\n    | null | \"\" ->\n        let start = Directory.GetCurrentDirectory()\n        let rec find (folder: string) =\n            if File.Exists(Path.Combine(folder, \"lawspec.json\")) || Directory.Exists(Path.Combine(folder, \"recorded\")) then\n                Path.Combine(folder, \"recorded\")\n            else\n                match Directory.GetParent folder with\n                | null -> Path.Combine(start, \"recorded\")\n                | parent -> find parent.FullName\n        find start\n    | given -> given\n\n/// Compare a value's text with its recording, or record it under\n/// LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded).\n[<CompiledName(\"RecordedText\")>]\nlet recordedText (key: string) (text: string) : Value =\n    let path = Path.Combine(Array.append [| recordedRoot () |] (key.Split '/'))\n    if Environment.GetEnvironmentVariable \"LAWSPEC_UPDATE_RECORDED\" = \"1\" then\n        Directory.CreateDirectory(Path.GetDirectoryName path) |> ignore\n        File.WriteAllText(path, text + \"\\n\")\n        Bool true\n    elif File.Exists path then\n        let stored = File.ReadAllText path\n        let stored = if stored.EndsWith \"\\n\" then stored.Substring(0, stored.Length - 1) else stored\n        if stored = text then Bool true\n        else\n            Fail.raiseWith \"RecordingDiffers\"\n                (\"recorded/\" + key + \" differs: expected \" + stored + \", actual \" + text\n                 + \" (lawspec test --update-recorded records the new value)\")\n    else\n        Fail.raiseWith \"RecordingMissing\"\n            (\"no recording recorded/\" + key + \"; run lawspec test --update-recorded to record \" + text)\n\n/// A recorded value, at its type.\n[<CompiledName(\"Recorded\")>]\nlet recorded (key: Value) (value: Value) (t: TypeRef) (schema: Schema.Schema) : Value =\n    match key with\n    | Text k -> recordedText k (Recorded.text value t (Some schema))\n    | _ -> Fail.raiseWith \"TextRequired\" \"recorded\"\n\n/// A built-in helper by name.\n[<CompiledName(\"Helper\")>]\nlet helper (name: string) (values: Value list) (types: string list) (bits: int) : Value =\n    match name, values with\n    | \"unreachable\", _ -> Fail.raiseWith \"Unreachable\" \"\"\n    | \"regexMatches\", [ Text pattern; Text text ] -> Bool(Regex.matches pattern text)\n    | \"recorded\", [ Text key; value ] when List.length types < 2 -> recordedText key (Recorded.renderPlain value)\n    | \"recorded\", [ key; value ] -> recorded key value (Scalar.typeOf (List.item 1 types)) (Schema.create [] [] bits)\n    | _ -> Scalar.helper name values types bits\n\nlet private unwrap (e: exn) =\n    match e with\n    | :? AggregateException as a when a.InnerExceptions.Count = 1 -> a.InnerExceptions.[0]\n    | _ -> e\n\n/// Run steps concurrently, each on the thread pool, and return their values\n/// in source order. Every step finishes before the first failure in source\n/// order is raised.\n[<CompiledName(\"Concurrently\")>]\nlet concurrently (steps: (unit -> Value) list) : Value list =\n    let tasks = steps |> List.map (fun step -> Task.Run(fun () -> step ())) |> Array.ofList\n    try Task.WaitAll(tasks |> Array.map (fun t -> t :> Task)) with _ -> ()\n    tasks\n    |> Array.map (fun t ->\n        if t.IsFaulted then raise (unwrap t.Exception)\n        elif t.IsCanceled then Fail.raiseWith \"ConcurrentStepCancelled\" \"\"\n        else t.Result)\n    |> List.ofArray\n\n/// Await an async adapter's task where it is called.\n[<CompiledName(\"Await\")>]\nlet await (task: Task<'a>) : 'a =\n    try task.GetAwaiter().GetResult() with e -> raise (unwrap e)\n"
dotnetSource "LawSpec.Runtime/Scalar.fs" = "/// LawSpec's scalar domain on .NET. Exact arithmetic never goes through a\n/// native float, and IEEE values are rounded once, from an exact ratio, to\n/// nearest with ties to even. Every generated law and dynamic definition uses\n/// these operations, so F# and C# agree with each other and with the other\n/// targets. ref:DEC-portable-exact-arithmetic ref:ieee-754\n/// ref:DEC-explicit-machine-profile\nmodule LawSpec.Runtime.Scalar\n\nopen System\nopen System.Collections.Concurrent\nopen System.Numerics\nopen System.Text\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n// ---------------------------------------------------------------------------\n// Type keys\n\nlet private tokenize (text: string) =\n    let tokens = ResizeArray<string>()\n    let word = StringBuilder()\n    let flush () =\n        if word.Length > 0 then\n            tokens.Add(word.ToString())\n            word.Clear() |> ignore\n    for c in text do\n        match c with\n        | '(' | ')' ->\n            flush ()\n            tokens.Add(string c)\n        | ' ' | '\\t' -> flush ()\n        | c -> word.Append(c) |> ignore\n    flush ()\n    List.ofSeq tokens\n\nlet rec private application parts =\n    match parts with\n    | [ Named(name, []) ] -> Named(name, [])\n    | Named(name, []) :: args when List.contains name [ \"List\"; \"Maybe\"; \"Optional\"; \"Nullable\" ] ->\n        Named(name, [ application args ])\n    | Named(name, []) :: args -> Named(name, args)\n    | [ t ] -> t\n    | _ -> fail \"InvalidTypeKey\" \"\"\n\nlet rec private parts tokens acc =\n    match tokens with\n    | [] -> List.rev acc, []\n    | \")\" :: _ -> List.rev acc, tokens\n    | \"(\" :: rest ->\n        let inner, after = parts rest []\n        match after with\n        | \")\" :: next -> parts next (application inner :: acc)\n        | _ -> fail \"InvalidTypeKey\" \"\"\n    | word :: rest -> parts rest (Named(word, []) :: acc)\n\nlet private typeCache = ConcurrentDictionary<string, TypeRef>()\n\n/// The type a key names: `Either (Int8) (Text)`, `List Int8`, `Maybe (List Text)`.\n/// Parentheses keep nested Either and presence arguments apart.\n[<CompiledName(\"TypeOf\")>]\nlet typeOf (key: string) : TypeRef =\n    typeCache.GetOrAdd(key, fun key ->\n        let found, rest = parts (tokenize key) []\n        if not (List.isEmpty rest) then fail \"InvalidTypeKey\" key\n        application found)\n\n/// The key of a type, as typeOf reads it.\n[<CompiledName(\"TypeKey\")>]\nlet rec typeKey (t: TypeRef) =\n    match t with\n    | Named(name, []) -> name\n    | Named(name, args) -> name + String.Join(\"\", args |> List.map (fun a -> \" (\" + typeKey a + \")\"))\n    | Parameter i -> sprintf \"$%d\" i\n\nlet private nameOf (t: TypeRef) =\n    match t with\n    | Named(name, _) -> name\n    | Parameter _ -> \"\"\n\n// ---------------------------------------------------------------------------\n// Integers\n\nlet private integerTypes =\n    set [ \"Int8\"; \"Int16\"; \"Int32\"; \"Int64\"; \"UInt8\"; \"UInt16\"; \"UInt32\"; \"UInt64\"\n          \"IntSize\"; \"UIntSize\"; \"UIntPtr\"; \"Integer\"; \"BigInt\"; \"BigUInt\" ]\n\n/// Whether a scalar name is one of LawSpec's integer types.\n[<CompiledName(\"IsIntegerType\")>]\nlet isIntegerType name = integerTypes.Contains name\n\nlet private pow2 (n: int) = BigInteger.One <<< n\n\nlet private signed (width: int) = Some(-(pow2 (width - 1))), Some(pow2 (width - 1) - BigInteger.One)\n\n/// An integer type's inclusive bounds under a machine profile (32 or 64 bits).\n[<CompiledName(\"Bounds\")>]\nlet bounds (name: string) (bits: int) : BigInteger option * BigInteger option =\n    if bits <> 32 && bits <> 64 then fail \"InvalidMachineBits\" (string bits)\n    match name with\n    | \"Integer\" | \"BigInt\" -> None, None\n    | \"BigUInt\" -> Some BigInteger.Zero, None\n    | \"IntSize\" -> signed bits\n    | \"UIntSize\" | \"UIntPtr\" -> Some BigInteger.Zero, Some(pow2 bits - BigInteger.One)\n    | _ when name.StartsWith \"UInt\" -> Some BigInteger.Zero, Some(pow2 (int (name.Substring 4)) - BigInteger.One)\n    | _ when name.StartsWith \"Int\" -> signed (int (name.Substring 3))\n    | _ -> fail \"UnknownInteger\" name\n\nlet private checkBounds (value: BigInteger) name bits =\n    let lo, hi = bounds name bits\n    let below = match lo with Some l -> value < l | None -> false\n    let above = match hi with Some h -> value > h | None -> false\n    if below || above then fail \"IntegerOutOfRange\" (sprintf \"%s %O\" name value)\n    Int value\n\n// ---------------------------------------------------------------------------\n// Exact numbers\n\n/// A normalized fraction.\n[<CompiledName(\"Ratio\")>]\nlet ratio (n: BigInteger) (d: BigInteger) =\n    if d.IsZero then fail \"InvalidRational\" \"zero denominator\"\n    let g = BigInteger.GreatestCommonDivisor(n, d)\n    let s = if d.Sign < 0 then BigInteger.MinusOne else BigInteger.One\n    Ratio(s * n / g, BigInteger.Abs d / g)\n\nlet private pow10 (n: int) = BigInteger.Pow(BigInteger(10), n)\n\nlet private normalized n d =\n    match ratio n d with\n    | Ratio(a, b) -> a, b\n    | _ -> failwith \"unreachable\"\n\n// IEEE layouts: fraction bits, exponent bits, bias.\nlet private format width =\n    match width with\n    | 32 -> 23, 8, 127\n    | 64 -> 52, 11, 1023\n    | _ -> fail \"InvalidIeeeWidth\" (string width)\n\ntype private Decoded =\n    | Finite of sign: int * mantissa: BigInteger * exponent: int\n    | Infinity of sign: int\n    | NaN\n\nlet private decode width (bits: uint64) =\n    let p, e, bias = format width\n    let sign = int (bits >>> (width - 1)) &&& 1\n    let exponent = int ((bits >>> p) &&& ((1UL <<< e) - 1UL))\n    let fraction = bits &&& ((1UL <<< p) - 1UL)\n    let top = (1 <<< e) - 1\n    if exponent = top then (if fraction = 0UL then Infinity sign else NaN)\n    elif exponent = 0 then Finite(sign, BigInteger(fraction), 1 - bias - p)\n    else Finite(sign, BigInteger((1UL <<< p) + fraction), exponent - bias - p)\n\n/// The exact ratio of an exact number or a finite float.\n[<CompiledName(\"Exact\")>]\nlet exact (value: Value) : BigInteger * BigInteger =\n    match value with\n    | Int n -> n, BigInteger.One\n    | Ratio(n, d) -> n, d\n    | Decimal(c, _) when c.IsZero -> BigInteger.Zero, BigInteger.One\n    | Decimal(c, e) when e >= 0 -> c * pow10 e, BigInteger.One\n    | Decimal(c, e) -> normalized c (pow10 -e)\n    | Float(w, b) ->\n        match decode w b with\n        | Finite(sign, m, e) ->\n            let signedM = if sign = 0 then m else -m\n            if e >= 0 then signedM <<< e, BigInteger.One else normalized signedM (pow2 -e)\n        | _ -> fail \"NonFiniteExactConversion\" \"\"\n    | _ -> fail \"ExactNumberRequired\" (sprintf \"%A\" value)\n\nlet private isExact value =\n    match value with\n    | Int _ | Ratio _ | Decimal _ -> true\n    | _ -> false\n\nlet rec private factors (n: BigInteger) (factor: BigInteger) count =\n    if (n % factor).IsZero then factors (n / factor) factor (count + 1) else n, count\n\n/// A decimal for an exact ratio, when its expansion terminates in base ten.\nlet private finiteDecimal n d =\n    let rn, rd = normalized n d\n    let d2, twos = factors rd (BigInteger 2) 0\n    let d5, fives = factors d2 (BigInteger 5) 0\n    if not d5.IsOne then fail \"NonTerminatingDecimal\" \"\"\n    let scale = max twos fives\n    Value.Decimal(rn * BigInteger.Pow(BigInteger 2, scale - twos) * BigInteger.Pow(BigInteger 5, scale - fives), -scale)\n\n// ---------------------------------------------------------------------------\n// IEEE floats\n\nlet private floatValue width (bits: uint64) =\n    if width = 32 && bits > 0xFFFFFFFFUL then fail \"InvalidIeeeBits\" \"\"\n    Float(width, bits)\n\nlet private zero width sign = Float(width, uint64 sign <<< (width - 1))\n\nlet private infinity width sign =\n    let p, e, _ = format width\n    Float(width, (uint64 sign <<< (width - 1)) ||| (((1UL <<< e) - 1UL) <<< p))\n\nlet private nan width =\n    let p, _, _ = format width\n    match infinity width 0 with\n    | Float(_, inf) -> Float(width, inf ||| (1UL <<< (p - 1)))\n    | _ -> failwith \"unreachable\"\n\nlet private floorLog2 (n: BigInteger) (d: BigInteger) =\n    let guess = int (n.GetBitLength()) - int (d.GetBitLength())\n    let below = if guess >= 0 then n < (d <<< guess) else (n <<< -guess) < d\n    if below then guess - 1 else guess\n\nlet private roundRatio (n: BigInteger) (d: BigInteger) =\n    let q = BigInteger.Divide(n, d)\n    let r = n - q * d\n    if BigInteger 2 * r > d || (BigInteger 2 * r = d && not q.IsEven) then q + BigInteger.One else q\n\n/// The float of a width nearest an exact ratio; a zero takes the given sign.\n[<CompiledName(\"FloatFromRatio\")>]\nlet floatFromRatio width (n: BigInteger) (d: BigInteger) zeroSign =\n    if d.IsZero then fail \"ZeroDenominator\" \"\"\n    if n.IsZero then zero width zeroSign else\n    let p, _, bias = format width\n    let s = if (n.Sign < 0) <> (d.Sign < 0) then 1 else 0\n    let an, ad = BigInteger.Abs n, BigInteger.Abs d\n    let exponent = max (1 - bias) (floorLog2 an ad)\n    let shift = p - exponent\n    let mantissa = if shift >= 0 then roundRatio (an <<< shift) ad else roundRatio an (ad <<< -shift)\n    let m, e = if mantissa >= pow2 (p + 1) then mantissa >>> 1, exponent + 1 else mantissa, exponent\n    if e > bias then infinity width s\n    else\n        let encoded = if m < pow2 p then 0UL else uint64 (e + bias)\n        let fraction = uint64 (m &&& (pow2 p - BigInteger.One))\n        Float(width, (uint64 s <<< (width - 1)) ||| (encoded <<< p) ||| fraction)\n\n/// A float's class: \"nan\", \"infinity\", \"zero\" or \"finite\".\n[<CompiledName(\"FloatClass\")>]\nlet floatClass value =\n    match value with\n    | Float(w, b) ->\n        match decode w b with\n        | NaN -> \"nan\"\n        | Infinity _ -> \"infinity\"\n        | Finite(_, m, _) when m.IsZero -> \"zero\"\n        | Finite _ -> \"finite\"\n    | _ -> fail \"FloatRequired\" \"\"\n\nlet private floatSign value =\n    match value with\n    | Float(w, b) -> int (b >>> (w - 1)) &&& 1\n    | _ -> 0\n\n/// A value as a float of a width: exact numbers round once, floats keep NaN\n/// and infinity and otherwise round their exact value.\n[<CompiledName(\"ToFloat\")>]\nlet toFloat value width =\n    match value with\n    | Float(w, _) when w = width -> value\n    | Float(w, b) ->\n        match decode w b with\n        | NaN -> nan width\n        | Infinity s -> infinity width s\n        | _ ->\n            let n, d = exact value\n            floatFromRatio width n d (floatSign value)\n    | _ ->\n        let n, d = exact value\n        floatFromRatio width n d 0\n\n/// A .NET double as a float of a width.\n[<CompiledName(\"FloatFromNative\")>]\nlet floatFromNative width (value: float) =\n    toFloat (Float(64, uint64 (BitConverter.DoubleToInt64Bits value))) width\n\n/// A float32 or float64's bits as LawSpec's float of that width.\n[<CompiledName(\"FloatFromSingle\")>]\nlet floatFromSingle (value: float32) =\n    Float(32, uint64 (BitConverter.SingleToUInt32Bits value))\n\n[<CompiledName(\"FloatFromDouble\")>]\nlet floatFromDouble (value: float) =\n    Float(64, BitConverter.DoubleToUInt64Bits value)\n\n[<CompiledName(\"ToSingle\")>]\nlet toSingle value =\n    match toFloat value 32 with\n    | Float(_, b) -> BitConverter.UInt32BitsToSingle(uint32 b)\n    | _ -> failwith \"unreachable\"\n\n[<CompiledName(\"ToDouble\")>]\nlet toDouble value =\n    match toFloat value 64 with\n    | Float(_, b) -> BitConverter.UInt64BitsToDouble b\n    | _ -> failwith \"unreachable\"\n\nlet private negateFloat value =\n    match value with\n    | Float(w, b) -> Float(w, b ^^^ (1UL <<< (w - 1)))\n    | _ -> value\n\nlet rec private floatOp op width a b =\n    let ca, cb = floatClass a, floatClass b\n    match op with\n    | _ when ca = \"nan\" || cb = \"nan\" -> nan width\n    | \"-\" -> floatOp \"+\" width a (negateFloat b)\n    | \"+\" when ca = \"infinity\" && cb = \"infinity\" -> if floatSign a = floatSign b then a else nan width\n    | \"+\" when ca = \"infinity\" -> a\n    | \"+\" when cb = \"infinity\" -> b\n    | \"*\" when (ca = \"infinity\" && cb = \"zero\") || (ca = \"zero\" && cb = \"infinity\") -> nan width\n    | \"*\" when ca = \"infinity\" || cb = \"infinity\" -> infinity width (floatSign a ^^^ floatSign b)\n    | \"/\" when ca = \"infinity\" && cb = \"infinity\" -> nan width\n    | \"/\" when ca = \"zero\" && cb = \"zero\" -> nan width\n    | \"/\" when ca = \"infinity\" -> infinity width (floatSign a ^^^ floatSign b)\n    | \"/\" when cb = \"zero\" -> infinity width (floatSign a ^^^ floatSign b)\n    | \"/\" when cb = \"infinity\" -> zero width (floatSign a ^^^ floatSign b)\n    | _ ->\n        let an, ad = exact a\n        let bn, bd = exact b\n        let n, d, zeroSign =\n            match op with\n            | \"+\" -> an * bd + bn * ad, ad * bd, floatSign a &&& floatSign b\n            | \"*\" -> an * bn, ad * bd, floatSign a ^^^ floatSign b\n            | \"/\" -> an * bd, ad * bn, floatSign a ^^^ floatSign b\n            | _ -> fail \"UnknownFloatOperation\" op\n        floatFromRatio width n d zeroSign\n\n/// IEEE arithmetic at the wider of the two widths.\n[<CompiledName(\"FloatBinary\")>]\nlet floatBinary op a b =\n    match a, b with\n    | Float(wa, _), Float(wb, _) ->\n        let w = max wa wb\n        floatOp op w (toFloat a w) (toFloat b w)\n    | _ -> fail \"FloatRequired\" op\n\nlet private order (a: BigInteger) (b: BigInteger) = compare a b |> sign\n\nlet private compareRatios (a: BigInteger, b: BigInteger) (c: BigInteger, d: BigInteger) = order (a * d) (c * b)\n\n/// The order of two floats, or None when one is NaN.\n[<CompiledName(\"FloatCompare\")>]\nlet floatCompare a b : int option =\n    match a, b with\n    | Float(wa, ba), Float(wb, bb) ->\n        match decode wa ba, decode wb bb with\n        | NaN, _ | _, NaN -> None\n        | Infinity s, Infinity t when s = t -> Some 0\n        | Infinity 1, _ -> Some -1\n        | _, Infinity 1 -> Some 1\n        | Infinity _, _ -> Some 1\n        | _, Infinity _ -> Some -1\n        | _ -> Some(compareRatios (exact a) (exact b))\n    | _ -> fail \"FloatRequired\" \"\"\n\nlet private toComplex value width =\n    match value with\n    | Value.Complex(_, r, i) -> Value.Complex(width, toFloat r width, toFloat i width)\n    | _ -> Value.Complex(width, toFloat value width, zero width 0)\n\n// ---------------------------------------------------------------------------\n// Text\n\n/// Whether a string is well-formed UTF-16: no lone surrogate.\n[<CompiledName(\"IsWellFormed\")>]\nlet isWellFormed (text: string) =\n    let mutable i = 0\n    let mutable ok = true\n    while ok && i < text.Length do\n        let c = text.[i]\n        if Char.IsHighSurrogate c then\n            if i + 1 < text.Length && Char.IsLowSurrogate text.[i + 1] then i <- i + 2 else ok <- false\n        elif Char.IsLowSurrogate c then ok <- false\n        else i <- i + 1\n    ok\n\n/// A text's Unicode scalar values.\n[<CompiledName(\"CodePoints\")>]\nlet codePoints (text: string) : int list =\n    [ for rune in text.EnumerateRunes() -> rune.Value ]\n\nlet private validUnit kind (n: int) =\n    match kind with\n    | \"Bytes\" -> n >= 0 && n <= 255\n    | \"CodeUnit16\" | \"Utf16Text\" -> n >= 0 && n <= 65535\n    | \"CodePoint\" | \"CodePointText\" -> n >= 0 && n <= 0x10FFFF\n    | _ -> n >= 0 && n <= 0x10FFFF && (n < 0xD800 || n > 0xDFFF)\n\nlet private checkedUnit kind n =\n    if not (validUnit kind n) then fail \"InvalidCharacter\" kind\n    n\n\n/// The text of Unicode scalar values.\n[<CompiledName(\"TextOf\")>]\nlet textOfPoints (points: int seq) =\n    let builder = StringBuilder()\n    for p in points do\n        builder.Append(Rune(checkedUnit \"Text\" p).ToString()) |> ignore\n    builder.ToString()\n\n/// Compare two well-formed strings by code point, which is UTF-8's byte order\n/// and LawSpec's text order (String.CompareOrdinal orders by UTF-16 units).\n[<CompiledName(\"CompareText\")>]\nlet compareText (a: string) (b: string) =\n    let fix (c: char) =\n        let n = int c\n        if n >= 0xD800 then (if n >= 0xE000 then n - 0x800 else n + 0x2000) else n\n    let n = min a.Length b.Length\n    let mutable i = 0\n    let mutable result = 0\n    while result = 0 && i < n do\n        result <- compare (fix a.[i]) (fix b.[i])\n        i <- i + 1\n    if result <> 0 then sign result else compare a.Length b.Length\n\n/// Compare two byte arrays as unsigned octets.\n[<CompiledName(\"CompareBytes\")>]\nlet compareBytes (a: byte[]) (b: byte[]) =\n    let c = ReadOnlySpan<byte>(a).SequenceCompareTo(ReadOnlySpan<byte>(b))\n    sign c\n\n// ---------------------------------------------------------------------------\n// Validation and conversion\n\nlet private floatType width = if width = 32 then \"Float32\" else \"Float64\"\n\n/// Check that a value belongs to a scalar or built-in container type under a\n/// machine profile, and return it.\n[<CompiledName(\"Validate\")>]\nlet rec validate (value: Value) (t: TypeRef) (bits: int) : Value =\n    match t, value with\n    | Named(\"Bool\", []), Bool _ -> value\n    | Named(\"Text\", []), Text s -> (if not (isWellFormed s) then fail \"InvalidUnicode\" \"\"); value\n    | Named(\"Bytes\", []), Bytes _ -> value\n    | Named((\"Char\" | \"CodePoint\" | \"CodeUnit16\") as kind, []), Int n ->\n        if n < BigInteger.Zero || n > BigInteger(0x10FFFF) then fail \"InvalidCharacter\" kind\n        checkedUnit kind (int n) |> ignore\n        value\n    | Named((\"CodePointText\" | \"Utf16Text\") as kind, []), Raw(k, units) when k = kind ->\n        units |> List.iter (checkedUnit kind >> ignore)\n        value\n    | Named(\"Decimal\", []), Decimal _ -> value\n    | Named(\"Rational\", []), Ratio(n, d) -> ratio n d\n    | Named(\"Float32\", []), Float(32, _) -> value\n    | Named(\"Float64\", []), Float(64, _) -> value\n    | Named(\"Complex64\", []), Value.Complex(32, r, i) ->\n        Value.Complex(32, validate r (Named(\"Float32\", [])) bits, validate i (Named(\"Float32\", [])) bits)\n    | Named(\"Complex128\", []), Value.Complex(64, r, i) ->\n        Value.Complex(64, validate r (Named(\"Float64\", [])) bits, validate i (Named(\"Float64\", [])) bits)\n    | Named(\"Symbol\", []), Symbol _ -> value\n    | Named(\"Unit\", []), Unit -> value\n    | Named(\"Null\", []), Null -> value\n    | Named(\"Undefined\", []), Undefined -> value\n    | Named(name, []), Int n when isIntegerType name -> checkBounds n name bits\n    | Named(\"List\", [ element ]), List items -> List(items |> List.map (fun v -> validate v element bits))\n    | Named(\"Maybe\", [ _ ]), Data(\"Maybe::Nothing\", []) -> value\n    | Named(\"Maybe\", [ inner ]), Data(\"Maybe::Just\", [ v ]) -> Data(\"Maybe::Just\", [ validate v inner bits ])\n    | Named(\"Either\", [ l; _ ]), Data(\"Either::Left\", [ v ]) -> Data(\"Either::Left\", [ validate v l bits ])\n    | Named(\"Either\", [ _; r ]), Data(\"Either::Right\", [ v ]) -> Data(\"Either::Right\", [ validate v r bits ])\n    | Named((\"Nullable\" | \"Optional\") as kind, [ inner ]), Presence(k, present) when k = kind ->\n        Presence(kind, present |> Option.map (fun v -> validate v inner bits))\n    | _ -> fail \"InvalidValue\" (typeKey t)\n\n/// An explicit conversion (`x :: T`): exact numbers convert exactly or fail,\n/// floats round once, and anything else is validated.\n[<CompiledName(\"Convert\")>]\nlet rec convert (value: Value) (t: TypeRef) (bits: int) : Value =\n    match t with\n    | Named(\"Rational\", []) -> exact value ||> ratio\n    | Named(\"Decimal\", []) -> exact value ||> finiteDecimal\n    | Named(\"Float32\", []) -> toFloat value 32\n    | Named(\"Float64\", []) -> toFloat value 64\n    | Named(\"Complex64\", []) -> toComplex value 32\n    | Named(\"Complex128\", []) -> toComplex value 64\n    | Named(name, []) when isIntegerType name ->\n        let n, d = exact value\n        if not (n % d).IsZero then fail \"FractionalConversion\" name\n        checkBounds (n / d) name bits\n    | Named(\"Nullable\", [ _ ]) when value = Null -> Presence(\"Nullable\", None)\n    | Named(\"Optional\", [ _ ]) when value = Undefined -> Presence(\"Optional\", None)\n    | Named((\"Nullable\" | \"Optional\") as kind, [ inner ]) ->\n        match value with\n        | Presence(k, present) when k = kind -> Presence(kind, present |> Option.map (fun v -> convert v inner bits))\n        | _ -> validate value t bits\n    | _ -> validate value t bits\n\n// ---------------------------------------------------------------------------\n// Equality, order and arithmetic\n\n/// LawSpec equality: structural, exact across exact numbers, and false for a\n/// NaN, even inside a container.\n[<CompiledName(\"Equal\")>]\nlet rec equal (a: Value) (b: Value) : bool =\n    match a, b with\n    | Float _, Float _ -> floatCompare a b = Some 0\n    | Value.Complex(_, r1, i1), Value.Complex(_, r2, i2) -> equal r1 r2 && equal i1 i2\n    | Value.Complex(w, r, i), Float _ -> equal r b && equal i (zero w 0)\n    | Float _, Complex _ -> equal b a\n    | Symbol(x, _), Symbol(y, _) -> Object.ReferenceEquals(x, y) || x.Equals y\n    | Presence(k1, Some x), Presence(k2, Some y) -> k1 = k2 && equal x y\n    | Presence(k1, None), Presence(k2, None) -> k1 = k2\n    | Data(t1, f1), Data(t2, f2) -> t1 = t2 && equalLists f1 f2\n    | List x, List y -> equalLists x y\n    | _ when isExact a && isExact b -> compareRatios (exact a) (exact b) = 0\n    | Bytes x, Bytes y -> compareBytes x y = 0\n    | Raw(k1, u1), Raw(k2, u2) -> k1 = k2 && u1 = u2\n    | Handle(n1, i1), Handle(n2, i2) -> n1 = n2 && (Object.ReferenceEquals(i1, i2) || i1.Equals i2)\n    | _ -> a = b\n\nand private equalLists xs ys =\n    match xs, ys with\n    | [], [] -> true\n    | x :: xs, y :: ys -> equal x y && equalLists xs ys\n    | _ -> false\n\n/// LawSpec's portable total order of keys. Floats, symbols and distinct\n/// handles have no portable order.\n[<CompiledName(\"Compare\")>]\nlet rec compareValues (a: Value) (b: Value) : int =\n    match a, b with\n    | Bool x, Bool y -> compare x y |> sign\n    | Text x, Text y -> compareText x y\n    | Bytes x, Bytes y -> compareBytes x y\n    | Raw(k1, x), Raw(k2, y) when k1 = k2 -> compare x y |> sign\n    | Presence(k1, None), Presence(k2, None) when k1 = k2 -> 0\n    | Presence(k1, None), Presence(k2, Some _) when k1 = k2 -> -1\n    | Presence(k1, Some _), Presence(k2, None) when k1 = k2 -> 1\n    | Presence(k1, Some x), Presence(k2, Some y) when k1 = k2 -> compareValues x y\n    | Data(\"Maybe::Nothing\", []), Data(\"Maybe::Just\", _) -> -1\n    | Data(\"Maybe::Just\", _), Data(\"Maybe::Nothing\", []) -> 1\n    | Data(t1, f1), Data(t2, f2) when t1 = t2 -> compareLists f1 f2\n    | Data(t1, _), Data(t2, _) -> compareText t1 t2\n    | List x, List y -> compareLists x y\n    | Handle(n1, i1), Handle(n2, i2) when n1 = n2 && Object.ReferenceEquals(i1, i2) -> 0\n    | Unit, Unit | Null, Null | Undefined, Undefined -> 0\n    | _ when isExact a && isExact b -> compareRatios (exact a) (exact b)\n    | _ -> fail \"NoPortableOrder\" \"\"\n\nand private compareLists xs ys =\n    match xs, ys with\n    | [], [] -> 0\n    | [], _ -> -1\n    | _, [] -> 1\n    | x :: xs, y :: ys ->\n        match compareValues x y with\n        | 0 -> compareLists xs ys\n        | c -> c\n\n/// A value's negation.\n[<CompiledName(\"Negate\")>]\nlet rec negate value =\n    match value with\n    | Int n -> Int(-n)\n    | Ratio(n, d) -> ratio (-n) d\n    | Decimal(c, e) -> Value.Decimal(-c, e)\n    | Float _ -> negateFloat value\n    | Value.Complex(w, r, i) -> Value.Complex(w, negate r, negate i)\n    | _ -> fail \"NumberRequired\" \"negate\"\n\nlet private inexactWidth (key: string) =\n    match key with\n    | \"Float32\" | \"Complex64\" -> 32\n    | \"Float64\" | \"Complex128\" -> 64\n    | _ -> 0\n\nlet private isComplexType (key: string) = key = \"Complex64\" || key = \"Complex128\"\n\nlet private relation op (ordering: int option) =\n    match ordering with\n    | None -> false\n    | Some n ->\n        match op with\n        | \"<\" -> n < 0\n        | \"<=\" -> n <= 0\n        | \">\" -> n > 0\n        | \">=\" -> n >= 0\n        | _ -> fail \"UnknownRelation\" op\n\nlet private exactBinary op a b (ta: string) (tb: string) =\n    match op, a, b with\n    | \"pow\", Int x, Int y when y.Sign >= 0 -> Int(BigInteger.Pow(x, int y))\n    | \"quot\", Int x, Int y when not y.IsZero -> Int(BigInteger.Divide(x, y))\n    | \"rem\", Int x, Int y when not y.IsZero -> Int(BigInteger.Remainder(x, y))\n    | _ ->\n        let an, ad = exact a\n        let bn, bd = exact b\n        let n, d =\n            match op with\n            | \"+\" -> an * bd + bn * ad, ad * bd\n            | \"-\" -> an * bd - bn * ad, ad * bd\n            | \"*\" -> an * bn, ad * bd\n            | \"/\" -> an * bd, ad * bn\n            | _ -> fail \"InvalidExactOperation\" op\n        let r = ratio n d\n        if op = \"/\" || ta = \"Rational\" || tb = \"Rational\" then r\n        elif ta = \"Decimal\" || tb = \"Decimal\" then finiteDecimal n d\n        else\n            match r with\n            | Ratio(i, _) -> Int i\n            | _ -> r\n\nlet private complexBinary op a b =\n    match a, b with\n    | Value.Complex(w, x, y), Value.Complex(_, u, v) ->\n        let f = floatBinary\n        let r, i =\n            match op with\n            | \"+\" | \"-\" -> f op x u, f op y v\n            | \"*\" -> f \"-\" (f \"*\" x u) (f \"*\" y v), f \"+\" (f \"*\" x v) (f \"*\" y u)\n            | \"/\" ->\n                let den = f \"+\" (f \"*\" u u) (f \"*\" v v)\n                f \"/\" (f \"+\" (f \"*\" x u) (f \"*\" y v)) den, f \"/\" (f \"-\" (f \"*\" y u) (f \"*\" x v)) den\n            | _ -> fail \"UnknownComplexOperation\" op\n        Value.Complex(w, r, i)\n    | _ -> fail \"ComplexRequired\" op\n\n/// A binary operator on two values of the given types (by key).\n[<CompiledName(\"Binary\")>]\nlet binary (op: string) (a: Value) (b: Value) (ta: string) (tb: string) : Value =\n    match op with\n    | \"==\" -> Bool(equal a b)\n    | \"!=\" -> Bool(not (equal a b))\n    | \"<\" | \"<=\" | \">\" | \">=\" ->\n        let ordering =\n            if inexactWidth ta > 0 || inexactWidth tb > 0 then floatCompare a b\n            else Some(compareValues a b)\n        Bool(relation op ordering)\n    | _ ->\n        if (inexactWidth ta > 0) <> (inexactWidth tb > 0) then fail \"ExactInexactMixing\" op\n        match max (inexactWidth ta) (inexactWidth tb) with\n        | 0 -> exactBinary op a b ta tb\n        | width when isComplexType ta || isComplexType tb -> complexBinary op (toComplex a width) (toComplex b width)\n        | _ -> floatBinary op a b\n\n// ---------------------------------------------------------------------------\n// Helpers\n\nlet private sequenceItems value (kind: string) =\n    match value with\n    | List items -> items\n    | Text s when kind = \"Text\" -> codePoints s |> List.map (BigInteger >> Int)\n    | Text s -> Encoding.UTF8.GetBytes s |> Seq.map (int >> BigInteger >> Int) |> List.ofSeq\n    | Bytes b -> b |> Seq.map (int >> BigInteger >> Int) |> List.ofSeq\n    | _ -> fail \"SequenceRequired\" kind\n\nlet private sequenceLike value (kind: string) (items: Value list) =\n    let ints = items |> List.map (function Int n -> int n | _ -> fail \"SequenceRequired\" kind)\n    match value with\n    | List _ -> List items\n    | Text _ when kind = \"Text\" -> Text(textOfPoints ints)\n    | _ -> Bytes(ints |> List.map byte |> Array.ofList)\n\nlet private bool value =\n    match value with\n    | Bool b -> b\n    | _ -> fail \"BoolRequired\" \"\"\n\nlet private integer value =\n    match value with\n    | Int n -> n\n    | _ -> fail \"IntegerRequired\" \"\"\n\nlet private text value =\n    match value with\n    | Text s -> s\n    | _ -> fail \"TextRequired\" \"\"\n\nlet private clamp (n: BigInteger) (lo: BigInteger) (hi: BigInteger) = if n < lo then lo elif n > hi then hi else n\n\n/// A built-in helper by name, with its arguments and their type keys.\n[<CompiledName(\"Helper\")>]\nlet helper (name: string) (values: Value list) (types: string list) (bits: int) : Value =\n    match name, values with\n    | \"isNaN\", [ f ] -> Bool(floatClass f = \"nan\")\n    | \"isInfinite\", [ f ] -> Bool(floatClass f = \"infinity\")\n    | \"isFinite\", [ f ] -> Bool(let c = floatClass f in c = \"finite\" || c = \"zero\")\n    | \"isNegativeZero\", [ f ] -> Bool(floatClass f = \"zero\" && floatSign f = 1)\n    | \"length\", [ List items ] -> Int(BigInteger(List.length items))\n    | \"length\", [ Bytes b ] -> Int(BigInteger b.Length)\n    | \"length\", [ Text s ] -> Int(BigInteger(List.length (codePoints s)))\n    | \"length\", [ Raw(_, units) ] -> Int(BigInteger(List.length units))\n    | (\"real\"), [ Value.Complex(_, r, _) ] -> r\n    | (\"imag\" | \"imaginary\"), [ Value.Complex(_, _, i) ] -> i\n    | \"conjugate\", [ Value.Complex(w, r, i) ] -> Value.Complex(w, r, negate i)\n    | \"abs\", [ v ] when isExact v -> if fst (exact v) < BigInteger.Zero then negate v else v\n    | \"abs\", [ Float(w, b) ] -> Float(w, b &&& ((1UL <<< (w - 1)) - 1UL))\n    | \"round\", [ v; Int places ] ->\n        let n, d = exact v\n        let places = int places\n        let sn, sd = if places >= 0 then n * pow10 places, d else n, d * pow10 -places\n        let q = roundRatio (BigInteger.Abs sn) sd\n        Value.Decimal((if sn.Sign < 0 then -q else q), -places)\n    | \"startsWith\", [ Text t; Text p ] -> Bool(t.StartsWith(p, StringComparison.Ordinal))\n    | \"endsWith\", [ Text t; Text s ] -> Bool(t.EndsWith(s, StringComparison.Ordinal))\n    | \"textContains\", [ Text t; Text p ] -> Bool(p = \"\" || t.Contains(p, StringComparison.Ordinal))\n    | \"checked\", [ _ ] -> Bool true\n    | \"select\", [ Bool c; a; b ] -> if c then a else b\n    | \"compare\", [ a; b ] ->\n        let tag =\n            match compareValues a b with\n            | -1 -> \"Less\"\n            | 0 -> \"Equal\"\n            | _ -> \"Greater\"\n        Data(\"lawspec.collections::type::Ordering::\" + tag, [])\n    | \"isPresent\", [ Presence(_, p) ] -> Bool(Option.isSome p)\n    | \"presentValue\", [ Presence(_, Some v) ] -> v\n    | \"presentValue\", [ Presence(_, None) ] -> fail \"AbsentPresenceValue\" \"\"\n    | \"negate\", [ v ] -> negate v\n    | \"append\", [ List a; List b ] -> List(a @ b)\n    | \"append\", [ Text a; Text b ] -> Text(a + b)\n    | \"append\", [ Bytes a; Bytes b ] -> Bytes(Array.append a b)\n    | \"slice\", [ x; Int from; Int until ] ->\n        let kind = List.head types\n        let items = sequenceItems x kind\n        let count = BigInteger(List.length items)\n        let i = clamp from BigInteger.Zero count\n        let j = clamp until i count\n        sequenceLike x kind (items |> List.skip (int i) |> List.take (int (j - i)))\n    | \"at\", [ x; Int i ] ->\n        let items = sequenceItems x (List.head types)\n        if i.Sign >= 0 && i < BigInteger(List.length items) then Data(\"Maybe::Just\", [ List.item (int i) items ])\n        else Data(\"Maybe::Nothing\", [])\n    | \"range\", [ Int lo; Int hi ] ->\n        List [ let mutable n = lo\n               while n < hi do\n                   yield Int n\n                   n <- n + BigInteger.One ]\n    | \"octets\", [ Bytes b ] -> List(b |> Seq.map (int >> BigInteger >> Int) |> List.ofSeq)\n    | \"bytesOf\", [ List items ] -> Bytes(items |> List.map (integer >> int >> byte) |> Array.ofList)\n    | \"utf8\", [ Text t ] -> Bytes(Encoding.UTF8.GetBytes t)\n    | \"textOf\", [ Int n ] -> Text(n.ToString())\n    | \"join\", [ Text separator; List parts ] -> Text(String.Join(separator, parts |> List.map text))\n    | (\"quot\" | \"rem\" | \"pow\"), [ a; b ] -> binary name a b (List.item 0 types) (List.item 1 types)\n    | _, [ v ] -> convert v (typeOf name) bits\n    | _ -> fail \"UnknownHelper\" name\n\n// ---------------------------------------------------------------------------\n// Symbols\n\n/// A fresh symbol with a description.\n[<CompiledName(\"NewSymbol\")>]\nlet newSymbol (description: string) = Symbol(obj (), description)\n\n/// Literal symbols share identities within one context (a law's run).\ntype SymbolContext() =\n    let symbols = ConcurrentDictionary<string, obj>()\n    member _.Identity(id: string) = symbols.GetOrAdd(id, fun _ -> obj ())\n\n/// A literal symbol, interned in its context.\n[<CompiledName(\"Symbol\")>]\nlet symbol (context: SymbolContext) (id: string) (description: string) = Symbol(context.Identity id, description)\n\n// ---------------------------------------------------------------------------\n// Literals, as the generated code writes them\n\n[<CompiledName(\"Integer\")>]\nlet integerLiteral (digits: string) = Int(BigInteger.Parse(digits, Globalization.CultureInfo.InvariantCulture))\n\n[<CompiledName(\"DecimalOf\")>]\nlet decimalOf (coefficient: string) (exponent: int) =\n    Value.Decimal(BigInteger.Parse(coefficient, Globalization.CultureInfo.InvariantCulture), exponent)\n\n[<CompiledName(\"RationalOf\")>]\nlet rationalOf (numerator: string) (denominator: string) =\n    ratio (BigInteger.Parse(numerator, Globalization.CultureInfo.InvariantCulture))\n        (BigInteger.Parse(denominator, Globalization.CultureInfo.InvariantCulture))\n\n[<CompiledName(\"FloatBits\")>]\nlet floatBits (width: int) (hex: string) =\n    floatValue width (UInt64.Parse(hex, Globalization.NumberStyles.HexNumber))\n\n[<CompiledName(\"TextUnits\")>]\nlet textUnits (points: int list) = Text(textOfPoints points)\n\n[<CompiledName(\"BytesOf\")>]\nlet bytesOf (units: int list) = Bytes(units |> List.map (checkedUnit \"Bytes\" >> byte) |> Array.ofList)\n\n[<CompiledName(\"RawOf\")>]\nlet rawOf (kind: string) (units: int list) = Raw(kind, units |> List.map (checkedUnit kind))\n"
dotnetSource "LawSpec.Runtime/Schema.fs" = "/// The checked shapes of a program's data: constructors, field types, GADT\n/// equations, existential witnesses, index guards and field contracts, all\n/// checked by one walk. ref:DEC-typed-core-boundary\n/// ref:DEC-gadts-and-index-arithmetic\nmodule LawSpec.Runtime.Schema\n\nopen System\nopen System.Numerics\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n/// Bounds and hints that steer the generation of one constructor field from\n/// the fields drawn before it. ref:DEC-shrink-within-domain\ntype FieldHints =\n    { Bounds: (string * Value) list\n      Lengths: (string * Value) list\n      Hints: Value list }\n\n/// A data constructor; Arguments and WitnessValues are filled in when it is\n/// instantiated at a type.\ntype Constructor =\n    { Tag: string\n      Fields: (string * TypeRef) list\n      Predicates: (Schema -> TypeRef list -> Value list -> bool) list\n      /// By field position, from 1.\n      Generators: Map<int, Schema -> TypeRef list -> Value list -> FieldHints>\n      Indices: string list\n      Refinements: (int * TypeRef) list\n      Existentials: int\n      Witnesses: int list\n      Arguments: TypeRef list\n      WitnessValues: Value list }\n\nand DataDefinition =\n    { Name: string\n      Parameters: int\n      Constructors: Constructor list\n      Handle: bool }\n\nand Schema =\n    { Definitions: Map<string, DataDefinition>\n      Arities: Map<string, int>\n      Bits: int }\n\n/// A constructor with only a tag and fields; the generated schema adds the rest.\nlet constructor tag fields =\n    { Tag = tag\n      Fields = fields\n      Predicates = []\n      Generators = Map.empty\n      Indices = []\n      Refinements = []\n      Existentials = 0\n      Witnesses = []\n      Arguments = []\n      WitnessValues = [] }\n\n/// The type parameters' types, by position.\nlet rec substitute (t: TypeRef) (known: Map<int, TypeRef>) =\n    match t with\n    | Parameter i -> defaultArg (known.TryFind i) t\n    | Named(name, args) -> Named(name, args |> List.map (fun a -> substitute a known))\n\nlet rec private checkScope (t: TypeRef) scope (schema: Schema) =\n    match t with\n    | Parameter i -> if i < 0 || i >= scope then fail \"UnboundSchemaParameter\" (string i)\n    | Named(name, args) ->\n        match schema.Arities.TryFind name with\n        | Some arity when arity = List.length args -> args |> List.iter (fun a -> checkScope a scope schema)\n        | _ -> fail \"UnknownTypeOrArity\" name\n\n/// Check that a closed type is known, with the right number of arguments.\nlet checkType (t: TypeRef) (schema: Schema) = checkScope t 0 schema\n\nlet private builtins = [ \"List\", 1; \"Maybe\", 1; \"Either\", 2; \"Nullable\", 1; \"Optional\", 1 ]\n\n/// A program's schema, from its data definitions and the scalar names.\nlet create (definitions: DataDefinition list) (primitives: string list) (bits: int) =\n    if bits <> 32 && bits <> 64 then fail \"InvalidMachineBits\" (string bits)\n    let names = (definitions |> List.map (fun d -> d.Name)) @ primitives @ (builtins |> List.map fst)\n    if List.length names <> List.length (List.distinct names) then fail \"DuplicateType\" \"\"\n    let arities =\n        Map.ofList ((primitives |> List.map (fun p -> p, 0)) @ builtins @ (definitions |> List.map (fun d -> d.Name, d.Parameters)))\n    let schema =\n        { Definitions = definitions |> List.map (fun d -> d.Name, d) |> Map.ofList\n          Arities = arities\n          Bits = bits }\n    let tags = definitions |> List.collect (fun d -> d.Constructors |> List.map (fun c -> c.Tag))\n    if List.length tags <> List.length (List.distinct tags) then fail \"DuplicateConstructor\" \"\"\n    for d in definitions do\n        for c in d.Constructors do\n            let scope = d.Parameters + c.Existentials\n            for _, t in c.Fields do\n                checkScope t scope schema\n    schema\n\nlet rec private unify (pattern: TypeRef) (actual: TypeRef) (known: Map<int, TypeRef> option) =\n    match known with\n    | None -> None\n    | Some k ->\n        match pattern with\n        | Parameter i ->\n            match k.TryFind i with\n            | None -> Some(k.Add(i, actual))\n            | Some t when t = actual -> known\n            | Some _ -> None\n        | Named(name, ps) ->\n            match actual with\n            | Named(n, xs) when n = name && List.length ps = List.length xs ->\n                List.fold2 (fun acc p a -> unify p a acc) known ps xs\n            | _ -> None\n\nlet private instantiate (c: Constructor) (args: TypeRef list) =\n    let known = args |> List.mapi (fun i a -> i, a) |> Map.ofList\n    let bound =\n        c.Refinements |> List.fold (fun acc (i, pattern) -> unify pattern (List.item i args) acc) (Some known)\n    bound\n    |> Option.map (fun b ->\n        { c with\n            Arguments = args\n            Fields = c.Fields |> List.map (fun (n, t) -> n, substitute t b) })\n\nlet private builtinConstructors name (args: TypeRef list) =\n    match name, args with\n    | \"Maybe\", [ t ] -> Some [ constructor \"Maybe::Nothing\" []; constructor \"Maybe::Just\" [ \"value\", t ] ]\n    | \"Either\", [ a; b ] -> Some [ constructor \"Either::Left\" [ \"value\", a ]; constructor \"Either::Right\" [ \"value\", b ] ]\n    | _ -> None\n\n/// The constructors of a data type at its arguments, or None for a scalar or\n/// a list. A GADT constructor whose equations the arguments refute is absent.\nlet constructors (t: TypeRef) (schema: Schema) : Constructor list option =\n    checkType t schema\n    match t with\n    | Named(name, args) ->\n        match schema.Definitions.TryFind name with\n        | None -> builtinConstructors name args\n        | Some d -> Some(d.Constructors |> List.choose (fun c -> instantiate c args))\n    | Parameter _ -> None\n\n/// Each instance of a constructor's free existentials over Core's finite\n/// witness pool (Bool and Int32).\nlet witnessInstances (c: Constructor) =\n    let pool = [ Named(\"Bool\", []); Named(\"Int32\", []) ]\n    let assignments =\n        c.Witnesses |> List.fold (fun previous i -> [ for known in previous do for t in pool -> Map.add i t known ]) [ Map.empty ]\n    let kept = List.length c.Fields - List.length c.Witnesses\n    [ for known in assignments ->\n          { c with\n              Fields = c.Fields |> List.take kept |> List.map (fun (n, t) -> n, substitute t known)\n              WitnessValues = c.Witnesses |> List.map (fun i -> Text(Scalar.typeKey known.[i])) } ]\n\nlet private findConstructor tag (cs: Constructor list) =\n    match cs |> List.filter (fun c -> c.Tag = tag) with\n    | [ c ] -> c\n    | _ -> fail \"ForeignConstructor\" tag\n\nlet private witnessed (c: Constructor) (values: Value list) (schema: Schema) =\n    let texts = values |> List.skip (List.length values - List.length c.Witnesses)\n    let known =\n        List.zip c.Witnesses texts\n        |> List.map (fun (i, v) ->\n            match v with\n            | Text key -> i, Scalar.typeOf key\n            | _ -> fail \"InvalidWitness\" \"\")\n        |> Map.ofList\n    known |> Map.iter (fun _ t -> checkType t schema)\n    c.Fields |> List.map (fun (n, t) -> n, substitute t known)\n\n// ---------------------------------------------------------------------------\n// Index terms\n\nlet private tokens (text: string) = text.Split(' ', StringSplitOptions.RemoveEmptyEntries) |> List.ofArray\n\nlet private guard tokens =\n    match tokens with\n    | (\"==\" | \">=\") :: _ -> true\n    | _ -> false\n\nlet private indexBinary op (a: BigInteger option) (b: BigInteger option) =\n    match a, b with\n    | Some a, Some b ->\n        match op with\n        | \"+\" -> Some(a + b)\n        | \"-\" when a >= b -> Some(a - b)\n        | \"*\" -> Some(a * b)\n        | \"div\" when b.Sign > 0 -> Some(BigInteger.Divide(a, b))\n        | \"mod\" when b.Sign > 0 -> Some(BigInteger.Remainder(a, b))\n        | \"^\" when b.Sign >= 0 && b <= BigInteger 64 -> Some(BigInteger.Pow(a, int b))\n        | _ -> None\n    | _ -> None\n\nlet rec private evalIndex terms (c: Constructor) (values: Value list) schema =\n    match terms with\n    | (term: string) :: rest when term.StartsWith \"c\" -> Some(BigInteger.Parse(term.Substring 1)), rest\n    | term :: rest when term.StartsWith \"f\" ->\n        let position, inner =\n            match term.Substring(1).Split('.') with\n            | [| p |] -> int p, 0\n            | [| p; i |] -> int p, int i\n            | _ -> fail \"InvalidIndexTerm\" term\n        let _, t = List.item position c.Fields\n        Some(index (List.item position values) t inner schema), rest\n    | op :: rest ->\n        let a, next = evalIndex rest c values schema\n        let b, after = evalIndex next c values schema\n        indexBinary op a b, after\n    | [] -> fail \"InvalidIndexTerm\" \"\"\n\n/// The index at a position of an indexed family's value.\nand index (value: Value) (t: TypeRef) (position: int) (schema: Schema) : BigInteger =\n    match value, constructors t schema with\n    | Data(tag, values), Some cs ->\n        let c0 = findConstructor tag cs\n        let c = { c0 with Fields = witnessed c0 values schema }\n        let terms = c.Indices |> List.map tokens |> List.filter (guard >> not)\n        if position < 0 || position >= List.length terms then fail \"NoIndex\" \"\"\n        match evalIndex (List.item position terms) c values schema with\n        | Some v, [] -> v\n        | _ -> fail \"UndefinedIndex\" tag\n    | _ -> fail \"IndexedTypeRequiresData\" (Scalar.typeKey t)\n\nlet private checkIndices (c: Constructor) values schema =\n    for text in c.Indices do\n        match tokens text with\n        | ((\"==\" | \">=\") as op) :: rest ->\n            let a, next = evalIndex rest c values schema\n            let b, _ = evalIndex next c values schema\n            let holds =\n                match a, b with\n                | Some a, Some b -> if op = \"==\" then a = b else a >= b\n                | _ -> false\n            if not holds then fail \"RefinementViolation\" (\"index guard \" + text)\n        | _ -> ()\n\n// ---------------------------------------------------------------------------\n// Validation\n\nlet rec private strictOrder values =\n    match values with\n    | a :: (b :: _ as rest) -> Scalar.compareValues a b = -1 && strictOrder rest\n    | _ -> true\n\nlet private checkCollection (name: string) (fields: Value list) =\n    match name, fields with\n    | \"lawspec.collections::type::Set\", [ List items ] ->\n        if not (strictOrder items) then fail \"RefinementViolation\" name\n    | \"lawspec.collections::type::KeyVal\", [ List entries ] ->\n        let keys = entries |> List.map (function Data(_, [ k; _ ]) -> k | _ -> fail \"InvalidValue\" name)\n        if not (strictOrder keys) then fail \"RefinementViolation\" name\n    | _ -> ()\n\nlet private checkPredicates (c: Constructor) args values schema =\n    for predicate in c.Predicates do\n        if not (predicate schema args values) then fail \"RefinementViolation\" c.Tag\n\n/// Check a value against a type: shape, field contracts, index guards and the\n/// canonical order of collections. Returns the value.\nlet rec validate (value: Value) (t: TypeRef) (schema: Schema) : Value =\n    checkType t schema\n    walk value t schema true\n\nand private walk value t schema deep =\n    match t, value with\n    | Named(\"List\", [ element ]), List items -> List(items |> List.map (fun v -> walk v element schema deep))\n    | Named((\"Optional\" | \"Nullable\") as kind, [ inner ]), Presence(k, present) when k = kind ->\n        Presence(kind, present |> Option.map (fun v -> walk v inner schema deep))\n    | Named(name, _), _ ->\n        match schema.Definitions.TryFind name with\n        | Some d when d.Handle ->\n            match value with\n            | Handle(n, _) when n = name -> value\n            | _ -> fail \"InvalidHandle\" name\n        | _ ->\n            match constructors t schema with\n            | None -> Scalar.validate value t schema.Bits\n            | Some cs -> walkData value t cs schema deep\n    | Parameter _, _ -> fail \"UnboundSchemaParameter\" \"\"\n\nand private walkData value t cs schema deep =\n    match value with\n    | Data(tag, fields) ->\n        let c = findConstructor tag cs\n        if List.length fields <> List.length c.Fields then fail \"WrongFieldCount\" tag\n        let typed = witnessed c fields schema\n        let converted = if deep then List.map2 (fun f (_, ft) -> walk f ft schema deep) fields typed else fields\n        let args = match t with Named(_, a) -> a | _ -> []\n        checkPredicates c args converted schema\n        checkIndices { c with Fields = typed } converted schema\n        checkCollection (match t with Named(n, _) -> n | _ -> \"\") converted\n        Data(tag, converted)\n    | _ -> fail \"ExpectedData\" (Scalar.typeKey t)\n\n/// Build a value from checked fields: the fields are not walked again, but\n/// the constructor's contracts are checked.\nlet construct (tag: string) (fields: Value list) (t: TypeRef) (schema: Schema) : Value =\n    match tag, fields with\n    | \"List::Nil\", [] -> List []\n    | \"List::Cons\", [ head; List tail ] -> List(head :: tail)\n    | _ ->\n        checkType t schema\n        match constructors t schema with\n        | Some cs -> walkData (Data(tag, fields)) t cs schema false\n        | None -> fail \"ExpectedData\" (Scalar.typeKey t)\n\n/// Branch on a value's constructor.\nlet matchValue (value: Value) (branches: Map<string, Value list -> 'a>) : 'a =\n    match value with\n    | List [] -> branches.[\"List::Nil\"] []\n    | List(head :: tail) -> branches.[\"List::Cons\"] [ head; List tail ]\n    | Data(tag, fields) ->\n        match branches.TryFind tag with\n        | Some branch -> branch fields\n        | None -> fail \"MatchFailure\" tag\n    | _ -> fail \"ExpectedData\" \"\"\n\n/// The field types of a checked data value (a recording uses them to tell Text\n/// from Bytes and Char from an integer).\nlet fieldTypes (value: Value) (t: TypeRef) (schema: Schema) =\n    match value, constructors t schema with\n    | Data(tag, values), Some cs ->\n        let c = findConstructor tag cs\n        witnessed c values schema |> List.map snd\n    | _ -> fail \"ExpectedData\" (Scalar.typeKey t)\n\n// ---------------------------------------------------------------------------\n// Payloads\n\ntype private Recipe =\n    | NoPayload\n    | Predicate of (Value -> bool)\n    | Container of string * Recipe list\n\nlet rec private recipe (t: TypeRef) (args: Recipe list) =\n    match t with\n    | Parameter i -> if i < List.length args then List.item i args else NoPayload\n    | Named(name, fields) ->\n        let children = fields |> List.map (fun f -> recipe f args)\n        if children |> List.forall (function NoPayload -> true | _ -> false) then NoPayload\n        else Container(name, children)\n\nlet rec private payload (r: Recipe) (value: Value) (schema: Schema) =\n    match r, value with\n    | NoPayload, _ -> true\n    | Predicate p, _ -> p value\n    | Container(\"List\", [ inner ]), List items -> items |> List.forall (fun v -> payload inner v schema)\n    | Container(_, [ _ ]), Presence(_, None) -> true\n    | Container(_, [ inner ]), Presence(_, Some v) -> payload inner v schema\n    | Container(\"Maybe\", _), Data(\"Maybe::Nothing\", []) -> true\n    | Container(\"Maybe\", [ inner ]), Data(\"Maybe::Just\", [ v ]) -> payload inner v schema\n    | Container(\"Either\", [ inner; _ ]), Data(\"Either::Left\", [ v ]) -> payload inner v schema\n    | Container(\"Either\", [ _; inner ]), Data(\"Either::Right\", [ v ]) -> payload inner v schema\n    | Container(name, args), Data(tag, values) ->\n        let c = findConstructor tag schema.Definitions.[name].Constructors\n        List.forall2 (fun (_, ft) v -> payload (recipe ft args) v schema) c.Fields values\n    | _ -> fail \"InvalidPayload\" \"\"\n\n/// Whether every payload of a container (each value at a type parameter)\n/// satisfies that parameter's predicate.\nlet allPayloads (value: Value) (t: TypeRef) (predicates: (Value -> bool) list) (schema: Schema) =\n    match t with\n    | Named(name, args) ->\n        if List.length args <> List.length predicates then fail \"PayloadArityMismatch\" name\n        validate value t schema |> ignore\n        payload (Container(name, predicates |> List.map Predicate)) value schema\n    | Parameter _ -> fail \"UnboundSchemaParameter\" \"\"\n\n// ---------------------------------------------------------------------------\n// Builders, as the generated schema module writes a program's data\n\n/// A field's name and type (by key).\nlet field (name: string) (key: string) = name, Scalar.typeOf key\n\n/// A data definition.\nlet definition (name: string) (parameters: int) (constructors: Constructor list) (handle: bool) =\n    { Name = name; Parameters = parameters; Constructors = constructors; Handle = handle }\n\nlet withPredicates predicates (c: Constructor) = { c with Predicates = predicates }\n\nlet withGenerators (generators: (int * (Schema -> TypeRef list -> Value list -> FieldHints)) list) (c: Constructor) =\n    { c with Generators = Map.ofList generators }\n\nlet withIndices indices (c: Constructor) = { c with Indices = indices }\n\nlet withRefinements refinements (c: Constructor) = { c with Refinements = refinements }\n\nlet withExistentials count (c: Constructor) = { c with Existentials = count }\n\nlet withWitnesses witnesses (c: Constructor) = { c with Witnesses = witnesses }\n\n/// A refinement of a parameter, by position, to a type (by key).\nlet refinement (index: int) (key: string) = index, Scalar.typeOf key\n\n/// A constructor contract's known parameter types, by position.\nlet known (types: TypeRef list) = types |> List.mapi (fun i t -> i, t) |> Map.ofList\n\n/// A field's generation hints.\nlet hints bounds lengths values = { Bounds = bounds; Lengths = lengths; Hints = values }\n"
dotnetSource "LawSpec.Runtime/Values.fs" = "/// LawSpec's portable values, as the generated laws and the dynamic\n/// definitions see them. Native F# and C# code never handles these directly:\n/// generated codecs convert at the boundary to records, unions and the .NET\n/// types the adapters use. ref:DEC-fsharp-runtime-from-scratch\n/// ref:DEC-typed-core-boundary\nnamespace LawSpec.Runtime\n\nopen System\nopen System.Numerics\n\n/// A value in LawSpec's portable domain. Exact numbers stay exact, IEEE\n/// values keep their bits (so a NaN payload and a negative zero survive), and\n/// data is a constructor tag with its fields in declaration order.\n[<StructuralEquality; NoComparison>]\ntype Value =\n    | Bool of bool\n    | Int of BigInteger\n    /// A normalized fraction: positive denominator, lowest terms.\n    | Ratio of numerator: BigInteger * denominator: BigInteger\n    /// coefficient * 10 ^ exponent, with the scale it was written with.\n    | Decimal of coefficient: BigInteger * exponent: int\n    | Float of width: int * bits: uint64\n    | Complex of width: int * real: Value * imaginary: Value\n    /// Unicode text; it never holds a lone surrogate.\n    | Text of string\n    | Bytes of byte[]\n    /// CodePointText and Utf16Text: their units, without validation as text.\n    | Raw of kind: string * units: int list\n    | Unit\n    | Null\n    | Undefined\n    /// Two symbols are equal when they share an identity.\n    | Symbol of identity: obj * description: string\n    | List of Value list\n    | Data of tag: string * fields: Value list\n    /// Nullable or Optional: absent, or present with a value.\n    | Presence of kind: string * value: Value option\n    /// A handle's identity crosses the native boundary unchanged.\n    | Handle of name: string * identity: obj\n\n/// A type as the runtime checks it: a name applied to arguments, or a data\n/// declaration's parameter by position.\n[<StructuralEquality; StructuralComparison>]\ntype TypeRef =\n    | Named of name: string * arguments: TypeRef list\n    | Parameter of index: int\n\n/// A broken contract, an unmet law or a malformed value. The code names the\n/// kind of failure (StrategyOutsideRefinement, EquationFailed, ...), so test\n/// output names it the same way on every .NET target.\ntype LawSpecException(code: string, detail: string, context: string list, inner: exn) =\n    inherit Exception(\n        (match context with\n         | [] -> \"\"\n         | _ -> String.Join(\": \", List.rev context) + \": \")\n        + code\n        + (if String.IsNullOrEmpty detail then \"\" else \" \" + detail),\n        inner)\n    new(code, detail) = LawSpecException(code, detail, [], null)\n    member _.Code = code\n    member _.Detail = detail\n    member _.Context = context\n    /// The same failure, inside one more definition or law.\n    member this.Within(identity: string) =\n        LawSpecException(code, detail, identity :: context, this.InnerException)\n\n/// A failure an operation raised with `raise`, carrying its portable value\n/// until an `attempt` catches it. ref:DEC-typed-native-definitions\ntype RaisedFailure(ability: string, failure: Value) =\n    inherit Exception(\"LawSpec failure raised by \" + ability + \": \" + sprintf \"%A\" failure)\n    member _.Ability = ability\n    member _.Failure = failure\n\n/// Helpers for raising LawSpec's failures.\nmodule Fail =\n    /// Raise a LawSpec failure with a code and detail.\n    let inline raiseWith code detail : 'a = raise (LawSpecException(code, detail))\n\n    /// Fail unless the condition holds.\n    let inline require condition code detail =\n        if not condition then raiseWith code detail\n"
dotnetSource "LawSpec.Testing/Gen.fs" = "/// LawSpec's property engine for .NET: seeded SplitMix64 generation with\n/// integrated shrinking. A generator yields a rose tree, the value with the\n/// smaller values it may shrink to, so shrinking a bound input rebuilds the\n/// inputs that depend on it and every candidate stays inside the domain.\n/// ref:DEC-portable-seeded-generation ref:DEC-shrink-within-domain\n/// ref:DEC-fsharp-runtime-from-scratch\nnamespace LawSpec.Testing\n\nopen System.Numerics\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Random\n\n/// A value and, lazily, the values it shrinks to, best first.\ntype Tree<'a> =\n    { Value: 'a\n      Children: seq<Tree<'a>> }\n\nmodule Tree =\n    let leaf value = { Value = value; Children = Seq.empty }\n\n    let rec map (f: 'a -> 'b) (tree: Tree<'a>) =\n        { Value = f tree.Value\n          Children = tree.Children |> Seq.map (map f) }\n\n    /// Keep only the candidates a predicate accepts, with their own candidates.\n    let rec filter (keep: 'a -> bool) (tree: Tree<'a>) =\n        { tree with Children = tree.Children |> Seq.filter (fun t -> keep t.Value) |> Seq.map (filter keep) }\n\n    /// Candidates from a function of a value, unfolded.\n    let rec unfold (shrink: 'a -> seq<'a>) (value: 'a) =\n        { Value = value\n          Children = shrink value |> Seq.map (unfold shrink) }\n\n/// A generator: a seed and a size to a tree, or None for an empty domain,\n/// which discards the whole tuple of inputs.\ntype Gen<'a> = Gen of (Seed -> int -> Tree<'a> option)\n\nmodule Gen =\n    let run (Gen g) seed size = g seed size\n\n    let constant value = Gen(fun _ _ -> Some(Tree.leaf value))\n\n    /// An empty domain: the case is discarded and redrawn.\n    let empty<'a> : Gen<'a> = Gen(fun _ _ -> None)\n\n    let map f (Gen g) = Gen(fun seed size -> g seed size |> Option.map (Tree.map f))\n\n    let rec private bindTree (tree: Tree<'a>) (k: 'a -> Tree<'b> option) : Tree<'b> option =\n        k tree.Value\n        |> Option.map (fun inner ->\n            { Value = inner.Value\n              Children =\n                Seq.append\n                    (tree.Children |> Seq.choose (fun child -> bindTree child k))\n                    inner.Children })\n\n    /// A generator that depends on another's value. Shrinking the first value\n    /// regenerates the second from the same seed.\n    let bind (Gen g) (k: 'a -> Gen<'b>) =\n        Gen(fun seed size ->\n            let s1, s2 = split seed\n            g s1 size |> Option.bind (fun tree -> bindTree tree (fun a -> run (k a) s2 size)))\n\n    let sized (f: int -> Gen<'a>) = Gen(fun seed size -> run (f size) seed size)\n\n    let resize size (Gen g) = Gen(fun seed _ -> g seed size)\n\n    let private towards (origin: BigInteger) (value: BigInteger) =\n        if value = origin then Seq.empty\n        else\n            seq {\n                yield origin\n                let mutable distance = (value - origin) / BigInteger 2\n                while not distance.IsZero do\n                    yield value - distance\n                    distance <- distance / BigInteger 2\n                if BigInteger.Abs(value - origin) > BigInteger.One then\n                    yield (if value > origin then value - BigInteger.One else value + BigInteger.One)\n            }\n            |> Seq.distinct\n\n    /// An integer in an inclusive range, shrinking towards the value nearest\n    /// zero. An open end is limited by the size, exponentially, so large\n    /// magnitudes appear as the size grows.\n    let integer (lo: BigInteger option) (hi: BigInteger option) =\n        Gen(fun seed size ->\n            let reach = BigInteger.Pow(BigInteger 2, min 64 (2 + size / 2))\n            let lo' = match lo, hi with\n                      | Some l, _ -> l\n                      | None, Some h -> BigInteger.Min(BigInteger.Zero, h) - reach\n                      | None, None -> -reach\n            let hi' = match hi, lo with\n                      | Some h, _ -> h\n                      | None, Some l -> BigInteger.Max(BigInteger.Zero, l) + reach\n                      | None, None -> reach\n            if lo' > hi' then None\n            else\n                let n, _ = below (hi' - lo' + BigInteger.One) seed\n                let value = lo' + n\n                let origin = BigInteger.Min(BigInteger.Max(BigInteger.Zero, lo'), hi')\n                Some(Tree.unfold (towards origin) value))\n\n    let range (lo: int) (hi: int) = integer (Some(BigInteger lo)) (Some(BigInteger hi)) |> map int\n\n    /// One of several generators, shrinking towards the earlier ones.\n    let oneof (gens: Gen<'a> list) =\n        match gens with\n        | [] -> empty\n        | _ ->\n            let arr = Array.ofList gens\n            bind (range 0 (arr.Length - 1)) (fun i -> arr.[i])\n\n    /// A weighted choice, shrinking towards the earlier ones.\n    let frequency (choices: (int * Gen<'a>) list) =\n        let total = choices |> List.sumBy fst\n        if total <= 0 then empty\n        else\n            bind (range 0 (total - 1)) (fun n ->\n                let rec pick n choices =\n                    match choices with\n                    | [ (_, g) ] -> g\n                    | (w, g) :: rest -> if n < w then g else pick (n - w) rest\n                    | [] -> empty\n                pick n choices)\n\n    let rec private sequenceTrees (trees: Tree<'a> list) : Tree<'a list> =\n        let values = trees |> List.map (fun t -> t.Value)\n        let removals =\n            seq {\n                let n = List.length trees\n                if n > 0 then\n                    yield []\n                    if n > 1 then yield List.take (n / 2) trees\n                    for i in 0 .. n - 1 do\n                        yield List.removeAt i trees\n            }\n            |> Seq.map sequenceTrees\n        let replacements =\n            seq {\n                for i, t in List.indexed trees do\n                    for child in t.Children do\n                        yield sequenceTrees (List.updateAt i child trees)\n            }\n        { Value = values\n          Children = Seq.append removals replacements }\n\n    let rec private productTrees (trees: Tree<'a> list) : Tree<'a list> =\n        { Value = trees |> List.map (fun t -> t.Value)\n          Children =\n            seq {\n                for i, t in List.indexed trees do\n                    for child in t.Children do\n                        yield productTrees (List.updateAt i child trees)\n            } }\n\n    let private draws (gens: Gen<'a> list) seed size =\n        let rec go gens seed acc =\n            match gens with\n            | [] -> Some(List.rev acc)\n            | g :: rest ->\n                let s1, s2 = split seed\n                match run g s1 size with\n                | None -> None\n                | Some t -> go rest s2 (t :: acc)\n        go gens seed []\n\n    /// A fixed number of values, each shrinking in place.\n    let vector count (g: Gen<'a>) =\n        Gen(fun seed size -> draws (List.replicate count g) seed size |> Option.map productTrees)\n\n    /// Values of several generators, in order.\n    let tuple (gens: Gen<'a> list) = Gen(fun seed size -> draws gens seed size |> Option.map productTrees)\n\n    /// A list of a length the size limits, shrinking by removing items and by\n    /// shrinking them.\n    let list (g: Gen<'a>) =\n        Gen(fun seed size ->\n            let s1, s2 = split seed\n            let n, _ = below (BigInteger(size + 1)) s1\n            draws (List.replicate (int n) g) s2 size |> Option.map sequenceTrees)\n\n    /// Keep values a predicate accepts, redrawing up to a limit; candidates\n    /// are filtered too.\n    let constrain (limit: int) (predicate: 'a -> bool) (Gen g) =\n        Gen(fun seed size ->\n            let rec attempt seed n =\n                if n <= 0 then None\n                else\n                    let s1, s2 = split seed\n                    match g s1 size with\n                    | Some tree when predicate tree.Value -> Some(Tree.filter predicate tree)\n                    | _ -> attempt s2 (n - 1)\n            attempt seed limit)\n\n    /// A dependent input's domain: an impossible value discards the tuple, so\n    /// an earlier input is redrawn rather than retried in vain.\n    let refine (predicate: 'a -> bool) (g: Gen<'a>) =\n        bind g (fun value -> if predicate value then constant value else empty)\n\n    /// Draw until a predicate holds, failing the harness after a limit.\n    let suchThat (predicate: 'a -> bool) (limit: int) (onExhausted: unit -> unit) (Gen g) =\n        Gen(fun seed size ->\n            let rec attempt seed n =\n                if n <= 0 then\n                    onExhausted ()\n                    None\n                else\n                    let s1, s2 = split seed\n                    match g s1 size with\n                    | Some tree when predicate tree.Value -> Some(Tree.filter predicate tree)\n                    | _ -> attempt s2 (n - 1)\n            attempt seed (limit + 1))\n\n    /// A weighted mix of fixed values and a generator.\n    let withExamples (examples: 'a list) (g: Gen<'a>) =\n        match examples with\n        | [] -> g\n        | _ -> frequency [ 1, oneof (examples |> List.map constant); 9, g ]\n\n    let apply (f: Gen<'a -> 'b>) (x: Gen<'a>) = bind f (fun f -> map f x)\n"
dotnetSource "LawSpec.Testing/Generators.fs" = "/// Generation from a program's schema: scalars within their refinement\n/// bounds, lists within their lengths, and data within a structural budget\n/// that counts every node, so recursive types terminate without a hidden cap\n/// and deep singletons stay reachable. Indexed families are solved backwards\n/// from their target index. ref:DEC-structural-size-budget\n/// ref:DEC-shrink-within-domain ref:DEC-indexed-families-as-evidence\nmodule LawSpec.Testing.Generators\n\nopen System\nopen System.Collections.Generic\nopen System.Numerics\nopen System.Runtime.CompilerServices\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Schema\n\n/// A comparison bound on an input, or on its length.\ntype Bound =\n    | Compare of op: string * value: Value\n    | Length of op: string * value: Value\n\n/// A native generator for a data type, given generators for its arguments.\ntype Factory = Gen<Value> list -> Gen<Value>\n\n/// What generation reads beyond the schema: native generator factories by\n/// type name (from lawspec.json) and the attempts budget.\ntype Context =\n    { Schema: Schema\n      Symbols: Scalar.SymbolContext\n      Factories: Map<string, Factory>\n      Attempts: int }\n\nlet private minimums = ConditionalWeakTable<Schema, Dictionary<TypeRef * int, int option>>()\n\nlet private exactBound (value: Value) =\n    let n, d = Scalar.exact value\n    let floor = BigInteger.Divide(n, d) - (if n.Sign < 0 && not (BigInteger.Remainder(n, d)).IsZero then BigInteger.One else BigInteger.Zero)\n    let ceil = floor + (if (BigInteger.Remainder(n, d)).IsZero then BigInteger.Zero else BigInteger.One)\n    floor, ceil\n\nlet private lower (lo: BigInteger option) n = Some(match lo with None -> n | Some l -> BigInteger.Max(l, n))\nlet private upper (hi: BigInteger option) n = Some(match hi with None -> n | Some h -> BigInteger.Min(h, n))\n\nlet private limit (lo, hi) (op: string, value: Value) =\n    let floor, ceil = exactBound value\n    match op with\n    | \">\" -> lower lo (floor + BigInteger.One), hi\n    | \">=\" -> lower lo ceil, hi\n    | \"<\" -> lo, upper hi (ceil - BigInteger.One)\n    | \"<=\" -> lo, upper hi floor\n    | \"==\" -> lower lo ceil, upper hi floor\n    | _ -> lo, hi\n\nlet private lengths bounds = bounds |> List.choose (function Length(op, v) -> Some(op, v) | _ -> None)\nlet private comparisons bounds = bounds |> List.choose (function Compare(op, v) -> Some(op, v) | _ -> None)\n\nlet private lengthRange bounds = lengths bounds |> List.fold limit (Some BigInteger.Zero, None)\n\nlet private lengthAllowed n bounds =\n    let lo, hi = lengthRange bounds\n    let n = BigInteger(n: int)\n    (match lo with Some l -> n >= l | None -> true) && (match hi with Some h -> n <= h | None -> true)\n\nlet private lengthGenerator bounds (size: int) =\n    match lengthRange bounds with\n    | Some lo, Some hi when lo > hi -> Gen.empty\n    | lo, hi ->\n        let lo = defaultArg lo BigInteger.Zero\n        Gen.integer (Some lo) (upper hi (BigInteger.Max(lo, BigInteger size))) |> Gen.map int\n\nlet private sequenceOf (element: Gen<'a>) bounds =\n    match lengths bounds with\n    | [] -> Gen.list element\n    | _ -> Gen.sized (fun size -> Gen.bind (lengthGenerator bounds size) (fun count -> Gen.vector count element))\n\nlet private unicodeScalar =\n    Gen.oneof [ Gen.integer (Some BigInteger.Zero) (Some(BigInteger 0xD7FF))\n                Gen.integer (Some(BigInteger 0xE000)) (Some(BigInteger 0x10FFFF)) ]\n\nlet private ieee width =\n    Gen.integer (Some BigInteger.Zero) (Some((BigInteger.One <<< width) - BigInteger.One))\n    |> Gen.map (fun bits -> Float(width, uint64 bits))\n\nlet private scalar (context: Context) (t: TypeRef) (bounds: Bound list) : Gen<Value> =\n    match t with\n    | Named(\"Bool\", []) -> Gen.oneof [ Gen.constant (Bool false); Gen.constant (Bool true) ]\n    | Named(\"Unit\", []) -> Gen.constant Unit\n    | Named(\"Null\", []) -> Gen.constant Null\n    | Named(\"Undefined\", []) -> Gen.constant Undefined\n    | Named(\"Rational\", []) ->\n        Gen.bind (Gen.integer None None) (fun n -> Gen.integer (Some BigInteger.One) None |> Gen.map (fun d -> Scalar.ratio n d))\n    | Named(\"Decimal\", []) ->\n        Gen.bind (Gen.integer None None) (fun c ->\n            Gen.sized (fun size -> Gen.range -size size |> Gen.map (fun e -> Value.Decimal(c, e))))\n    | Named(\"Float32\", []) -> ieee 32\n    | Named(\"Float64\", []) -> ieee 64\n    | Named((\"Complex64\" | \"Complex128\") as name, []) ->\n        let w = if name = \"Complex64\" then 32 else 64\n        Gen.bind (ieee w) (fun r -> ieee w |> Gen.map (fun i -> Value.Complex(w, r, i)))\n    | Named(\"Char\", []) -> unicodeScalar |> Gen.map Int\n    | Named(\"CodePoint\", []) -> Gen.integer (Some BigInteger.Zero) (Some(BigInteger 0x10FFFF)) |> Gen.map Int\n    | Named(\"CodeUnit16\", []) -> Gen.integer (Some BigInteger.Zero) (Some(BigInteger 0xFFFF)) |> Gen.map Int\n    | Named(\"Text\", []) -> sequenceOf unicodeScalar bounds |> Gen.map (List.map int >> Scalar.textOfPoints >> Text)\n    | Named(\"Bytes\", []) ->\n        sequenceOf (Gen.integer (Some BigInteger.Zero) (Some(BigInteger 255))) bounds\n        |> Gen.map (fun units -> Bytes(units |> List.map byte |> Array.ofList))\n    | Named((\"CodePointText\" | \"Utf16Text\") as name, []) ->\n        let top = if name = \"CodePointText\" then 0x10FFFF else 0xFFFF\n        sequenceOf (Gen.integer (Some BigInteger.Zero) (Some(BigInteger top))) bounds\n        |> Gen.map (fun units -> Raw(name, units |> List.map int))\n    | Named(\"Symbol\", []) ->\n        Gen.integer (Some BigInteger.Zero) None\n        |> Gen.map (fun n ->\n            let key = n.ToString()\n            Value.Symbol(context.Symbols.Identity(\"generated:\" + key), key))\n    | Named(name, []) when Scalar.isIntegerType name ->\n        let lo, hi = comparisons bounds |> List.fold limit (Scalar.bounds name context.Schema.Bits)\n        match lo, hi with\n        | Some l, Some h when l > h -> Gen.empty\n        | _ -> Gen.integer lo hi |> Gen.map Int\n    | _ -> Fail.raiseWith \"NoGenerator\" (Scalar.typeKey t)\n\n/// Whether a value is a member of its type, contracts included.\nlet accepted (value: Value) (t: TypeRef) (schema: Schema) =\n    try\n        validate value t schema |> ignore\n        true\n    with :? LawSpecException as e when e.Code = \"RefinementViolation\" -> false\n\nlet rec private valueNodes (value: Value) =\n    match value with\n    | Data(_, fields) -> 1 + (fields |> List.sumBy valueNodes)\n    | Presence(_, Some v) -> 1 + valueNodes v\n    | List items -> 1 + (items |> List.sumBy (fun v -> 1 + valueNodes v))\n    | _ -> 1\n\n/// Sets and maps are canonical: sorted and without duplicate keys, also\n/// after every shrink.\nlet private canonical (t: TypeRef) (value: Value) =\n    let distinctSorted key items =\n        items\n        |> List.sortWith (fun a b -> Scalar.compareValues (key a) (key b))\n        |> List.fold (fun acc item ->\n            match acc with\n            | last :: _ when Scalar.compareValues (key last) (key item) = 0 -> acc\n            | _ -> item :: acc) []\n        |> List.rev\n    match t, value with\n    | Named(\"lawspec.collections::type::Set\", _), Data(tag, [ List items ]) -> Data(tag, [ List(distinctSorted id items) ])\n    | Named(\"lawspec.collections::type::KeyVal\", _), Data(tag, [ List entries ]) ->\n        Data(tag, [ List(distinctSorted (function Data(_, [ k; _ ]) -> k | v -> v) entries) ])\n    | _ -> value\n\nlet private factory (context: Context) (t: TypeRef) =\n    match t with\n    | Named(name, _) -> context.Factories.TryFind name\n    | _ -> None\n\nlet rec private inhabited (context: Context) (t: TypeRef) budget =\n    if budget < 1 then false\n    else\n        match t with\n        | Named((\"List\" | \"Optional\" | \"Nullable\"), _) -> true\n        | _ when (factory context t).IsSome -> true\n        | _ ->\n            match constructors t context.Schema with\n            | None -> true\n            | Some cs ->\n                cs |> List.collect witnessInstances\n                |> List.exists (fun (c: Constructor) -> Option.isSome (allocation context c.Fields (budget - 1 - List.length c.WitnessValues)))\n\n/// The least structural cost of a type, if it is at most the limit.\nand minimum (context: Context) (t: TypeRef) (limit: int) : int option =\n    if limit < 1 then None\n    else\n        let cache = minimums.GetValue(context.Schema, fun _ -> Dictionary())\n        let key = t, limit\n        match lock cache (fun () -> match cache.TryGetValue key with | true, v -> Some v | _ -> None) with\n        | Some cost -> cost\n        | None ->\n            let cost = seq { 1 .. limit } |> Seq.tryFind (fun c -> inhabited context t c)\n            lock cache (fun () -> cache.[key] <- cost)\n            cost\n\nand private costs (context: Context) (fields: (string * TypeRef) list) (budget: int) =\n    match fields with\n    | [] -> if budget >= 0 then Some [] else None\n    | _ when budget < 1 -> None\n    | (_, t) :: rest ->\n        minimum context t budget\n        |> Option.bind (fun cost -> costs context rest (budget - cost) |> Option.map (fun more -> cost :: more))\n\n/// Each field's budget: its minimum, plus an even share of what is left.\nand allocation (context: Context) (fields: (string * TypeRef) list) (budget: int) =\n    costs context fields budget\n    |> Option.map (fun minimums ->\n        match minimums with\n        | [] -> []\n        | _ ->\n            let extra = budget - List.sum minimums\n            let count = List.length minimums\n            minimums |> List.mapi (fun i cost -> cost + extra / count + (if i < extra % count then 1 else 0)))\n\nlet private withWitnesses (native: Gen<Value>) (witnesses: Value list) = Gen.withExamples witnesses native\n\nlet rec private build (context: Context) (t: TypeRef) (budget: int) (bounds: Bound list) : Gen<Value> =\n    match factory context t with\n    | Some f -> custom context t budget bounds f\n    | None -> buildNative context t budget bounds\n\nand private custom (context: Context) (t: TypeRef) (budget: int) (bounds: Bound list) (f: Factory) =\n    let args = match t with Named(_, a) -> a | _ -> []\n    let children =\n        args\n        |> List.map (fun child ->\n            let available = max 1 (budget - 1)\n            match minimum context child available with\n            | None -> Gen.empty\n            | Some _ -> build context child available [])\n    let checkedGen = f children |> Gen.map (fun v -> validate v t context.Schema)\n    match bounds with\n    | [] -> checkedGen\n    | _ ->\n        checkedGen\n        |> Gen.refine (fun v ->\n            bounds\n            |> List.forall (function\n                | Length(op, b) -> Scalar.binary op (Scalar.helper \"length\" [ v ] [ Scalar.typeKey t ] context.Schema.Bits) b \"Integer\" \"Integer\" = Bool true\n                | Compare(op, b) -> Scalar.binary op v b (Scalar.typeKey t) (Scalar.typeKey t) = Bool true))\n\nand private buildNative (context: Context) (t: TypeRef) (budget: int) (bounds: Bound list) =\n    match t with\n    | Named(\"List\", [ element ]) ->\n        let lengthBounds = lengths bounds\n        let limitCost = if List.isEmpty lengthBounds then budget - 1 else max 64 (budget - 1)\n        match minimum context element limitCost with\n        | None -> Gen.constant (List []) |> Gen.refine (fun _ -> lengthAllowed 0 bounds)\n        | Some cost ->\n            Gen.bind (lengthGenerator bounds ((budget - 1) / cost)) (fun count ->\n                if count = 0 then Gen.constant (List [])\n                else Gen.vector count (build context element (max cost ((budget - 1) / count)) []) |> Gen.map List)\n    | Named((\"Optional\" | \"Nullable\") as kind, [ inner ]) ->\n        let absent = Gen.constant (Presence(kind, None))\n        match minimum context inner (budget - 1) with\n        | None -> absent\n        | Some _ -> Gen.oneof [ absent; build context inner (budget - 1) [] |> Gen.map (fun v -> Presence(kind, Some v)) ]\n    | _ ->\n        match constructors t context.Schema with\n        | None -> scalar context t bounds\n        | Some raw ->\n            let choices =\n                [ for c0 in raw do\n                      for c in witnessInstances c0 do\n                          match allocation context c.Fields (budget - 1 - List.length c.WitnessValues) with\n                          | Some shares -> yield constructorGen context c shares\n                          | None -> () ]\n            Gen.oneof choices\n            |> Gen.map (canonical t)\n            |> Gen.constrain context.Attempts (fun v -> accepted v t context.Schema)\n\nand private constructorGen (context: Context) (c: Constructor) (shares: int list) =\n    let rec fields (remaining: ((string * TypeRef) * int) list) (values: Value list) =\n        match remaining with\n        | [] -> Gen.constant (Data(c.Tag, values @ c.WitnessValues))\n        | ((_, ft), share) :: rest ->\n            let position = List.length values + 1\n            let hints =\n                match c.Generators.TryFind position with\n                | Some constraints -> Some(constraints context.Schema c.Arguments values)\n                | None -> None\n            let bounds, witnesses =\n                match hints with\n                | Some h -> (h.Bounds |> List.map Compare) @ (h.Lengths |> List.map Length), h.Hints\n                | None -> [], []\n            let native = build context ft share bounds\n            let g = if (factory context ft).IsSome then native else withWitnesses native witnesses\n            Gen.bind g (fun v -> fields rest (values @ [ v ]))\n    fields (List.zip c.Fields shares) []\n\n// ---------------------------------------------------------------------------\n// Indexed families\n\ntype private Term =\n    | Constant of BigInteger\n    | Field of int\n    | Op of string * Term * Term\n\nlet private tokens (text: string) = text.Split(' ', StringSplitOptions.RemoveEmptyEntries) |> List.ofArray\n\nlet rec private parse tokens =\n    match tokens with\n    | (t: string) :: rest when t.StartsWith \"c\" -> Constant(BigInteger.Parse(t.Substring 1)), rest\n    | t :: rest when t.StartsWith \"f\" -> Field(int (t.Substring 1)), rest\n    | op :: rest ->\n        let a, next = parse rest\n        let b, after = parse next\n        Op(op, a, b), after\n    | [] -> Fail.raiseWith \"InvalidIndexTerm\" \"\"\n\nlet rec private termFields term =\n    match term with\n    | Constant _ -> []\n    | Field i -> [ i ]\n    | Op(_, a, b) -> termFields a @ termFields b\n\nlet rec private evaluate term (assigned: Map<int, BigInteger>) =\n    match term with\n    | Constant n -> Some n\n    | Field i -> assigned.TryFind i\n    | Op(op, a, b) ->\n        match evaluate a assigned, evaluate b assigned with\n        | Some x, Some y ->\n            match op with\n            | \"+\" -> Some(x + y)\n            | \"-\" when x >= y -> Some(x - y)\n            | \"*\" -> Some(x * y)\n            | \"div\" when y.Sign > 0 -> Some(BigInteger.Divide(x, y))\n            | \"mod\" when y.Sign > 0 -> Some(BigInteger.Remainder(x, y))\n            | \"^\" when y.Sign >= 0 && y <= BigInteger 64 -> Some(BigInteger.Pow(x, int y))\n            | _ -> None\n        | _ -> None\n\ntype private Equation =\n    { Term: Term\n      Guards: (string * Term * Term) list\n      Positions: int list }\n\nlet private equation (texts: string list) =\n    match texts with\n    | text :: guards ->\n        let term, _ = parse (tokens text)\n        let parsed =\n            guards\n            |> List.map (fun g ->\n                match tokens g with\n                | op :: rest ->\n                    let a, next = parse rest\n                    let b, _ = parse next\n                    op, a, b\n                | [] -> Fail.raiseWith \"InvalidIndexGuard\" g)\n        let positions =\n            (termFields term @ (parsed |> List.collect (fun (_, a, b) -> termFields a @ termFields b))) |> List.distinct |> List.sort\n        { Term = term; Guards = parsed; Positions = positions }\n    | [] -> Fail.raiseWith \"InvalidIndexTerm\" \"\"\n\nlet private holds (relation, a, b) assigned =\n    match evaluate a assigned, evaluate b assigned with\n    | Some x, Some y -> if relation = \"==\" then x = y else x >= y\n    | _ -> false\n\n/// An indexed family's value whose index is the target (or, for a negative\n/// target, any of its smallest reachable indices).\nlet indexed (context: Context) (t: TypeRef) (target: BigInteger) (equations: Map<string, string list>) (budget: int) : Gen<Value> =\n    let parsed = equations |> Map.map (fun _ texts -> equation texts)\n    let positions (c: Constructor) = parsed.[c.Tag].Positions\n    let rec families pending (found: Map<TypeRef, Constructor list>) =\n        match pending with\n        | [] -> found\n        | t :: rest when found.ContainsKey t -> families rest found\n        | t :: rest ->\n            let cs =\n                match constructors t context.Schema with\n                | Some cs -> cs |> List.collect witnessInstances\n                | None -> Fail.raiseWith \"IndexedTypeRequiresData\" (Scalar.typeKey t)\n            let children = [ for c in cs do for i in positions c -> snd (List.item i c.Fields) ]\n            families (children @ rest) (found.Add(t, cs))\n    let all = families [ t ] Map.empty\n    let plain =\n        [ for KeyValue(_, cs) in all do\n              for c in cs do\n                  for i, (_, ft) in List.indexed c.Fields do\n                      if not (List.contains i (positions c)) then yield ft, minimum context ft 64 ]\n        |> Map.ofList\n    let limitIndex = int (BigInteger.Max(BigInteger.Zero, target)) + 16\n    let assignments (c: Constructor) (costs: Map<TypeRef * int, int>) =\n        let eq = parsed.[c.Tag]\n        let fields = c.Fields\n        let ok = fields |> List.indexed |> List.forall (fun (i, (_, ft)) -> List.contains i eq.Positions || (plain.[ft]).IsSome)\n        if not ok then []\n        else\n            let choices =\n                [ for i in eq.Positions ->\n                      let _, ft = List.item i fields\n                      i, (costs |> Map.toList |> List.choose (fun ((t0, k), _) -> if t0 = ft then Some k else None) |> List.sort) ]\n            let rec assign choices (assigned: Map<int, BigInteger>) =\n                let ready =\n                    eq.Guards |> List.filter (fun (_, a, b) -> (termFields a @ termFields b) |> List.forall assigned.ContainsKey)\n                if not (ready |> List.forall (fun g -> holds g assigned)) then []\n                else\n                    match choices with\n                    | [] -> [ assigned ]\n                    | (i, values) :: rest -> values |> List.collect (fun v -> assign rest (assigned.Add(i, BigInteger(v: int))))\n            [ for assigned in assign choices Map.empty do\n                  match evaluate eq.Term assigned with\n                  | Some value when value.Sign >= 0 && value <= BigInteger limitIndex ->\n                      let required =\n                          fields\n                          |> List.mapi (fun i (_, ft) ->\n                              match assigned.TryFind i with\n                              | Some k -> costs.[(ft, int k)]\n                              | None -> (plain.[ft]).Value)\n                      yield int value, assigned, required\n                  | _ -> () ]\n    let rec reach (costs: Map<TypeRef * int, int>) =\n        let next =\n            all\n            |> Map.fold (fun acc ft cs ->\n                cs\n                |> List.fold (fun table c ->\n                    assignments c costs\n                    |> List.fold (fun table (k, _, fields) ->\n                        let cost = 1 + List.length c.WitnessValues + List.sum fields\n                        match Map.tryFind (ft, k) table with\n                        | Some existing when existing <= cost -> table\n                        | _ -> Map.add (ft, k) cost table) table) acc) costs\n        if next = costs then costs else reach next\n    let costs = reach Map.empty\n    let solutions =\n        all\n        |> Map.fold (fun table ft cs ->\n            cs\n            |> List.fold (fun acc c ->\n                assignments c costs\n                |> List.fold (fun acc (k, targets, fields) ->\n                    let existing = defaultArg (Map.tryFind (ft, k) acc) []\n                    Map.add (ft, k) (existing @ [ c, targets, fields ]) acc) acc) table) Map.empty\n    let levels =\n        if target.Sign < 0 then\n            costs |> Map.toList |> List.choose (fun ((t0, k), _) -> if t0 = t then Some k else None) |> List.sort |> List.truncate 6\n        else [ int target ] |> List.filter (fun k -> costs.ContainsKey(t, k))\n    let rec generate ft k share =\n        let choices =\n            defaultArg (solutions.TryFind(ft, k)) []\n            |> List.filter (fun (c, _, fieldCosts) -> 1 + List.length c.WitnessValues + List.sum fieldCosts <= share)\n        Gen.bind (Gen.oneof (choices |> List.map Gen.constant)) (fun (c: Constructor, targets: Map<int, BigInteger>, fieldCosts: int list) ->\n            let count = List.length fieldCosts\n            let extra = share - 1 - List.length c.WitnessValues - List.sum fieldCosts\n            let children =\n                List.zip c.Fields fieldCosts\n                |> List.mapi (fun i ((_, childType), cost) ->\n                    let childShare = cost + (if count > 0 then extra / count + (if i < extra % count then 1 else 0) else 0)\n                    match targets.TryFind i with\n                    | Some index -> generate childType (int index) childShare\n                    | None -> build context childType childShare [])\n            Gen.tuple children |> Gen.map (fun values -> Data(c.Tag, values @ c.WitnessValues)))\n        |> Gen.constrain context.Attempts (fun v -> accepted v ft context.Schema)\n    match levels with\n    | [] when target.Sign < 0 -> Fail.raiseWith \"NoIndexedGenerator\" (Scalar.typeKey t)\n    | [] -> Gen.empty\n    | _ -> Gen.bind (Gen.oneof (levels |> List.map Gen.constant)) (fun k -> generate t k (max budget costs.[(t, k)]))\n\n/// A bound on an input.\nlet compareBound (op: string) (value: Value) = Compare(op, value)\n\n/// A bound on an input's length.\nlet lengthBound (op: string) (value: Value) = Length(op, value)\n\n/// No index to aim at.\nlet noIndex () : (BigInteger * Map<string, string list>) option = None\n\n/// An indexed family's target index and each constructor's index terms.\nlet index (target: Value) (tags: string list) (terms: string list list) =\n    match target with\n    | Int n -> Some(n, Map.ofList (List.zip tags terms))\n    | _ -> Fail.raiseWith \"IntegerRequired\" \"index target\"\n\n/// The generator of an input of a type: native factories first, then the\n/// type's structure within a budget that grows with the size.\nlet generator (context: Context) (t: TypeRef) (bounds: Bound list) (witnesses: Value list) (index: (BigInteger * Map<string, string list>) option) =\n    Gen.sized (fun size ->\n        match factory context t with\n        | Some f -> custom context t (size + 1) bounds f\n        | None ->\n            let limit = List.max (64 :: (witnesses |> List.map valueNodes))\n            match minimum context t limit with\n            | None -> Fail.raiseWith \"NoStructuralGenerator\" (Scalar.typeKey t)\n            | Some least ->\n                let budget = max least (size + 1)\n                match index with\n                | Some(target, equations) -> indexed context t target equations budget\n                | None -> withWitnesses (build context t budget bounds) witnesses)\n"
dotnetSource "LawSpec.Testing/Harness.fs" = "/// The harness plane on .NET: how often a law runs, how long it may take,\n/// whether its cases were adequate (cover, classify, labels), targeted\n/// search scores, known failures, skips and benchmarks. Statistics go to\n/// LAWSPEC_STATS as the same JSON records every target writes.\n/// ref:REQ-harness-units ref:DEC-never-pass-vacuously\nmodule LawSpec.Testing.Harness\n\nopen System\nopen System.Collections.Generic\nopen System.Diagnostics\nopen System.IO\nopen System.Security.Cryptography\nopen System.Text\nopen System.Text.Json\nopen System.Text.Json.Nodes\nopen System.Threading\nopen System.Threading.Tasks\nopen LawSpec.Runtime\n\n/// What one generated case observed: cover predicates, classifications,\n/// labels and a target score.\ntype Observation =\n    { Covers: Value list\n      Classes: (string * Value) list\n      Labels: Value list\n      Score: Value option }\n\ntype private State =\n    { Law: string\n      Test: string\n      mutable Failed: bool\n      mutable Cases: int\n      mutable Cover: int[]\n      Classes: SortedDictionary<string, int>\n      Labels: SortedDictionary<string, int>\n      mutable Target: bool\n      mutable Best: Value option\n      mutable Aborted: exn option\n      Extra: Dictionary<string, JsonNode> }\n\nlet private current = AsyncLocal<State option>()\n\nlet private ordinal = StringComparer.Ordinal\n\n/// Fail the harness itself (not the law): a strategy outside its input's\n/// refinement, a discard budget spent, a broken cover clause.\nlet abort (code: string) (detail: string) : 'a =\n    let failure = LawSpecException(code, detail)\n    match current.Value with\n    | Some state when state.Aborted.IsNone -> state.Aborted <- Some(failure :> exn)\n    | _ -> ()\n    raise failure\n\n/// Mark a failure as the harness's, keeping the failure itself.\nlet markHarnessFailure (failure: exn) =\n    match current.Value with\n    | Some state when state.Aborted.IsNone -> state.Aborted <- Some failure\n    | _ -> ()\n\nlet private boolean (value: Value) =\n    match value with\n    | Bool b -> b\n    | _ -> abort \"InvalidHarnessPredicate\" (sprintf \"%A\" value)\n\n/// Whether a score beats the best so far; a NaN never does.\nlet higher (score: Value) (best: Value option) =\n    match score with\n    | Float _ when Scalar.floatClass score = \"nan\" -> false\n    | Float _ ->\n        match best with\n        | None -> true\n        | Some other -> Scalar.floatCompare score other = Some 1\n    | Int _ | Ratio _ | Value.Decimal _ ->\n        match best with\n        | None -> true\n        | Some other -> Scalar.compareValues score other = 1\n    | _ -> abort \"InvalidTargetScore\" (sprintf \"%A\" score)\n\n/// A score as the reports print it.\nlet scoreText (score: Value) =\n    match score with\n    | Int n -> n.ToString()\n    | Ratio(n, d) -> n.ToString() + \"/\" + d.ToString()\n    | Value.Decimal(c, e) -> c.ToString() + \"e\" + string e\n    | Float(w, b) ->\n        match Scalar.floatClass score with\n        | \"nan\" -> \"NaN\"\n        | \"infinity\" -> if (b >>> (w - 1)) = 0UL then \"Infinity\" else \"-Infinity\"\n        | _ -> (Scalar.toDouble score).ToString(\"R\", Globalization.CultureInfo.InvariantCulture)\n    | _ -> sprintf \"%A\" score\n\nlet private observe (state: State) (o: Observation) =\n    if List.length o.Covers <> state.Cover.Length then abort \"InvalidHarnessCoverObservation\" \"\"\n    o.Covers |> List.iteri (fun i holds -> if boolean holds then state.Cover.[i] <- state.Cover.[i] + 1)\n    for label, _ in o.Classes do\n        if not (state.Classes.ContainsKey label) then state.Classes.[label] <- 0\n    for label in o.Classes |> List.filter (snd >> boolean) |> List.map fst |> List.distinct do\n        state.Classes.[label] <- state.Classes.[label] + 1\n    let labels =\n        o.Labels |> List.map (function Text s -> s | v -> abort \"InvalidHarnessLabel\" (sprintf \"%A\" v)) |> List.distinct\n    for label in labels do\n        state.Labels.[label] <- (match state.Labels.TryGetValue label with | true, n -> n | _ -> 0) + 1\n    match o.Score with\n    | None -> ()\n    | Some score ->\n        state.Target <- true\n        if higher score state.Best then state.Best <- Some score\n\n/// What a case observed.\nlet observation covers classes labels score = { Covers = covers; Classes = classes; Labels = labels; Score = score }\n\n/// One generated case: count it, record what it observed, then run it. After\n/// the first failure only the law runs (shrinking does not count cases).\nlet sample (observation: unit -> Observation) (test: unit -> Value) : Value =\n    match current.Value with\n    | None -> Fail.raiseWith \"HarnessObservationOutsideRun\" \"\"\n    | Some state when state.Failed ->\n        observation () |> ignore\n        test ()\n    | Some state ->\n        state.Cases <- state.Cases + 1\n        try\n            observe state (observation ())\n            test ()\n        with _ ->\n            state.Failed <- true\n            reraise ()\n\nlet private percentage n cases = if cases = 0 then 0.0 else Math.Round(10000.0 * float n / float cases) / 100.0\n\nlet private statsDirectory () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_STATS\" with\n    | null | \"\" -> None\n    | directory -> Some directory\n\nlet private writeRecord (identity: string) (record: JsonObject) =\n    match statsDirectory () with\n    | None -> ()\n    | Some directory ->\n        Directory.CreateDirectory directory |> ignore\n        let hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes identity))\n        let path = Path.Combine(directory, hash + \".json\")\n        let temporary = path + \".\" + string Environment.ProcessId + \".\" + Guid.NewGuid().ToString(\"N\") + \".tmp\"\n        try\n            File.WriteAllText(temporary, record.ToJsonString())\n            File.Move(temporary, path, true)\n        finally\n            if File.Exists temporary then File.Delete temporary\n\n/// The expected-failure context of a `known failing` law.\ntype private Expected =\n    { ExpectedLaw: string\n      Checks: ResizeArray<JsonObject>\n      mutable ExpectedAborted: exn option }\n\nlet private expected = AsyncLocal<Expected option>()\n\nlet private commit (record: JsonObject) =\n    let law = record.[\"law\"].GetValue<string>()\n    match expected.Value with\n    | Some e when e.ExpectedLaw = law ->\n        e.Checks.Add record\n        if record.ContainsKey \"failureKind\" && record.[\"failureKind\"].GetValue<string>() = \"harness\" && e.ExpectedAborted.IsNone then\n            e.ExpectedAborted <- Some(LawSpecException(\"HarnessFailed\", law) :> exn)\n    | _ -> writeRecord (law + \"\\u0000\" + record.[\"test\"].GetValue<string>()) record\n\nlet private node (value: obj) : JsonNode =\n    match value with\n    | :? JsonNode as n -> n\n    | :? string as s -> JsonValue.Create(s)\n    | :? int as i -> JsonValue.Create(i)\n    | :? int64 as i -> JsonValue.Create(i)\n    | :? float as f -> JsonValue.Create(f)\n    | :? bool as b -> JsonValue.Create(b)\n    | null -> null\n    | other -> JsonValue.Create(string other)\n\nlet private objectOf (fields: (string * obj) list) =\n    let o = JsonObject()\n    for k, v in fields do\n        o.[k] <- node v\n    o\n\ntype private CoverRow =\n    { Label: string\n      Required: int\n      Observed: float\n      Hits: int\n      Cases: int\n      Met: bool }\n\nlet private coverRows (covers: (int * string) list) (state: State) =\n    List.zip covers (List.ofArray state.Cover)\n    |> List.map (fun ((percent, label), n) ->\n        { Label = label\n          Required = percent\n          Observed = percentage n state.Cases\n          Hits = n\n          Cases = state.Cases\n          Met = state.Cases > 0 && 100 * n >= percent * state.Cases })\n\nlet private reportText (state: State) (rows: CoverRow list) =\n    let text = StringBuilder()\n    let line (s: string) = text.Append(s).Append('\\n') |> ignore\n    line (sprintf \"%s: %d generated case(s)\" state.Law state.Cases)\n    for row in rows do\n        let shortfall = if row.Met then \"\" else sprintf \" (not met; %d/%d cases)\" row.Hits row.Cases\n        line (sprintf \"  cover %d%% \\\"%s\\\": %.2f%%%s\" row.Required row.Label row.Observed shortfall)\n    for KeyValue(label, n) in state.Classes do\n        line (sprintf \"  %s: %.2f%%\" label (percentage n state.Cases))\n    for KeyValue(label, n) in state.Labels do\n        line (sprintf \"  label %s: %.2f%%\" label (percentage n state.Cases))\n    match state.Target, state.Best with\n    | true, Some best -> line (\"  best target score: \" + scoreText best)\n    | _ -> ()\n    text.ToString()\n\nlet private report (state: State) (rows: CoverRow list) =\n    let cover = JsonArray()\n    for row in rows do\n        cover.Add(objectOf [ \"label\", box row.Label; \"required\", box row.Required; \"observed\", box row.Observed\n                             \"hits\", box row.Hits; \"cases\", box row.Cases; \"met\", box row.Met ])\n    let classes = JsonObject()\n    for KeyValue(k, v) in state.Classes do classes.[k] <- JsonValue.Create(v)\n    let labels = JsonObject()\n    for KeyValue(k, v) in state.Labels do labels.[k] <- JsonValue.Create(v)\n    let o =\n        objectOf [ \"law\", box state.Law; \"test\", box state.Test; \"attempts\", box 1; \"cases\", box state.Cases\n                   \"cover\", box cover; \"classes\", box classes; \"labels\", box labels ]\n    if state.Target then\n        o.[\"target\"] <- objectOf [ \"best\", (match state.Best with Some b -> box (scoreText b) | None -> null) ]\n    for KeyValue(k, v) in state.Extra do\n        o.[k] <- v.DeepClone()\n    o\n\n/// Options of a controlled run.\ntype Options =\n    { Repeat: int\n      Retries: int\n      Timeout: int option\n      Resources: bool\n      Observed: bool }\n\nlet defaults = { Repeat = 1; Retries = 0; Timeout = None; Resources = false; Observed = true }\n\n/// A controlled run's options.\nlet options (repeat: int) (retries: int) (timeout: int option) (resources: bool) (observed: bool) =\n    { Repeat = repeat; Retries = retries; Timeout = timeout; Resources = resources; Observed = observed }\n\nlet private execute (law: string) (options: Options) (test: unit -> unit) : exn option =\n    match options.Timeout with\n    | None ->\n        try\n            test ()\n            None\n        with e -> Some e\n    | Some ms ->\n        let state = current.Value\n        let work = Task.Run(fun () ->\n            current.Value <- state\n            test ())\n        let finished = try work.Wait(ms) with _ -> true\n        if not finished then\n            let failure = LawSpecException(\"TestTimeout\", sprintf \"%s did not finish within %d ms\" law ms)\n            markHarnessFailure failure\n            Some(failure :> exn)\n        elif work.IsFaulted then\n            Some(match work.Exception.InnerExceptions.Count with\n                 | 1 -> work.Exception.InnerExceptions.[0]\n                 | _ -> work.Exception :> exn)\n        else None\n\n/// Run a test under the harness: each repeat is a complete check with its\n/// own counters, and a retry starts the repeats again. Coverage is never\n/// pooled across runs.\nlet run (law: string) (name: string) (covers: (int * string) list) (options: Options) (test: unit -> unit) =\n    let previous = current.Value\n    try\n        let rec attempts (attempt: int) (history: JsonObject list) =\n            let rec repeats (repetition: int) (runs: JsonObject list) =\n                let state =\n                    { Law = law; Test = name; Failed = false; Cases = 0; Cover = Array.zeroCreate covers.Length\n                      Classes = SortedDictionary(ordinal); Labels = SortedDictionary(ordinal); Target = false\n                      Best = None; Aborted = None; Extra = Dictionary() }\n                current.Value <- Some state\n                let failure = execute law options test\n                let rows = coverRows covers state\n                let unmet = rows |> List.filter (fun r -> not r.Met)\n                let reportObject = if options.Observed then report state rows else objectOf [ \"law\", box law; \"test\", box name ]\n                let text = if options.Observed then reportText state rows else \"\"\n                if options.Observed then Console.Out.Write text\n                let outcome, retryable =\n                    match failure, state.Aborted, unmet with\n                    | None, Some cause, _ -> Some cause, false\n                    | None, None, _ :: _ ->\n                        Some(LawSpecException(\"HarnessFailed\", law + \": UnmetCover\\n\" + text) :> exn), false\n                    | Some e, Some _, _ -> Some e, false\n                    | Some e, None, _ ->\n                        (if options.Observed && not (List.isEmpty covers) then\n                             Some(LawSpecException(\"PropertyFailed\", e.Message + \"\\n\" + text, [], e) :> exn)\n                         else Some e), true\n                    | None, None, [] -> None, true\n                let run = reportObject.DeepClone().AsObject()\n                run.Remove \"law\" |> ignore\n                run.Remove \"test\" |> ignore\n                run.Remove \"attempts\" |> ignore\n                run.[\"attempt\"] <- JsonValue.Create(attempt)\n                run.[\"repetition\"] <- JsonValue.Create(repetition)\n                run.[\"outcome\"] <- JsonValue.Create(if outcome.IsNone then \"passed\" else \"failed\")\n                let runs = run :: runs\n                match outcome with\n                | None when repetition < options.Repeat -> repeats (repetition + 1) runs\n                | _ -> outcome, retryable, reportObject, runs\n            let outcome, retryable, reportObject, runs = repeats 1 history\n            match outcome with\n            | Some _ when retryable && attempt <= options.Retries -> attempts (attempt + 1) runs\n            | _ ->\n                let status =\n                    match outcome with\n                    | None when attempt > 1 -> \"flaky\"\n                    | None -> \"passed\"\n                    | Some _ -> \"failed\"\n                reportObject.[\"outcome\"] <- JsonValue.Create(status)\n                reportObject.[\"attempts\"] <- JsonValue.Create(attempt)\n                if not retryable then reportObject.[\"failureKind\"] <- JsonValue.Create(\"harness\")\n                if options.Repeat <> 1 || options.Retries <> 0 then\n                    reportObject.[\"repeat\"] <- JsonValue.Create(options.Repeat)\n                    let array = JsonArray()\n                    for r in List.rev runs do array.Add(r)\n                    reportObject.[\"runs\"] <- array\n                match outcome with\n                | None ->\n                    commit reportObject\n                    if status = \"flaky\" then printfn \"%s is flaky: it failed, then passed on attempt %d\" law attempt\n                | Some e ->\n                    (try commit reportObject with r -> eprintfn \"LawSpec statistics failed for %s: %s\" law r.Message)\n                    raise e\n        attempts 1 []\n    finally\n        current.Value <- previous\n\n/// Record extra fields (a search's report) in the running test's record.\nlet record (fields: (string * JsonNode) list) =\n    match current.Value with\n    | Some state -> for k, v in fields do state.Extra.[k] <- v\n    | None -> ()\n\n/// A skipped law, recorded and reported.\nlet skip (law: string) (reason: string) =\n    eprintfn \"SKIPPED %s: %s\" law reason\n    commit (objectOf [ \"law\", box law; \"test\", box (law + \" skipped\"); \"outcome\", box \"skipped\"; \"reason\", box reason ])\n\n/// A law known to fail: its checks must fail, and a law that passes fails\n/// the run so the mark is removed.\nlet knownFailing (law: string) (name: string) (reason: string) (checks: (unit -> unit) list) =\n    let previous = expected.Value\n    let context = { ExpectedLaw = law; Checks = ResizeArray(); ExpectedAborted = None }\n    expected.Value <- Some context\n    let failure =\n        try\n            try\n                for check in checks do check ()\n                None\n            with e -> Some e\n        finally\n            expected.Value <- previous\n    let reports = JsonArray()\n    for c in context.Checks do reports.Add(c)\n    let record outcome extra =\n        let o = objectOf ([ \"law\", box law; \"test\", box name; \"reason\", box reason; \"outcome\", box outcome ] @ extra)\n        o.[\"checks\"] <- reports\n        commit o\n    match failure, context.ExpectedAborted with\n    | None, None ->\n        record \"known-failing-passed\" []\n        eprintfn \"%s is marked known failing (%s), but it passes; remove `known failing` from its harness\" law reason\n        Fail.raiseWith \"KnownFailingPassed\" (law + \" is marked known failing (\" + reason + \"), but it passes; remove `known failing` from its harness\")\n    | Some e, None ->\n        record \"known-failing\" [ \"failure\", box e.Message ]\n        printfn \"%s is known to fail (%s): %s\" law reason e.Message\n    | Some e, Some _ ->\n        record \"failed\" [ \"failureKind\", box \"harness\"; \"failure\", box e.Message ]\n        raise e\n    | None, Some cause ->\n        record \"failed\" [ \"failureKind\", box \"harness\" ]\n        raise cause\n\n/// Measure a body: at least three iterations, about 200 ms, at most 100,000.\nlet benchmark (unitName: string) (name: string) (body: unit -> unit) =\n    let started = Stopwatch.GetTimestamp()\n    let ticks = Stopwatch.Frequency\n    let toNs (t: int64) = t * 1_000_000_000L / ticks\n    let mutable count = 0L\n    let mutable total = 0L\n    let mutable fastest = Int64.MaxValue\n    let mutable go = true\n    while go && count < 100000L do\n        let before = Stopwatch.GetTimestamp()\n        if count >= 3L && toNs (before - started) >= 200_000_000L then go <- false\n        else\n            body ()\n            let elapsed = toNs (Stopwatch.GetTimestamp() - before)\n            fastest <- min fastest elapsed\n            total <- total + elapsed\n            count <- count + 1L\n    let mean = total / count\n    writeRecord (\"benchmark\\u0000\" + unitName + \"\\u0000\" + name)\n        (objectOf [ \"benchmark\", box name; \"unit\", box unitName; \"iterations\", box count; \"mean_ns\", box mean; \"min_ns\", box fastest ])\n    printfn \"benchmark %s: %d iteration(s), mean %.2f us, fastest %.2f us\" name count (float mean / 1000.0) (float fastest / 1000.0)\n\n/// Record that a parallel unit ran.\nlet recordParallel (unitName: string) (fields: (string * obj) list) =\n    writeRecord (\"parallel\\u0000\" + unitName) (objectOf ((\"parallel\", box unitName) :: fields))\n"
dotnetSource "LawSpec.Testing/LawSpec.Testing.fsproj" = "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <!-- Generated by LawSpec. Do not edit. LawSpec's property engine and harness. -->\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n    <TreatWarningsAsErrors>true</TreatWarningsAsErrors>\n    <IsPackable>false</IsPackable>\n  </PropertyGroup>\n  <ItemGroup>\n    <Compile Include=\"Gen.fs\" />\n    <Compile Include=\"Generators.fs\" />\n    <Compile Include=\"Harness.fs\" />\n    <Compile Include=\"Property.fs\" />\n  </ItemGroup>\n  <ItemGroup>\n    <ProjectReference Include=\"../LawSpec.Runtime/LawSpec.Runtime.fsproj\" />\n  </ItemGroup>\n</Project>\n"
dotnetSource "LawSpec.Testing/Property.fs" = "/// Running a law's property: draw cases from a seed, run each, and shrink the\n/// first failure to a small counterexample. One seed per run is printed with\n/// any failure, and LAWSPEC_SEED replays it. ref:DEC-portable-seeded-generation\n/// ref:DEC-never-pass-vacuously\nmodule LawSpec.Testing.Property\n\nopen System\nopen System.Numerics\nopen LawSpec.Runtime\n\n/// How many cases to run, how many discards a case may take, and how many\n/// shrink steps a failure may take.\ntype Settings =\n    { Cases: int\n      MaxAttempts: int\n      MaxShrinks: int }\n\nlet private random = System.Random.Shared\n\n/// The run's seed: LAWSPEC_SEED, or a fresh one.\nlet runSeed () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n    | null | \"\" -> BigInteger(random.NextInt64())\n    | text -> BigInteger.Parse text\n\nlet private render (values: Value list) =\n    \"(\" + String.Join(\", \", values |> List.map Recorded.renderPlain) + \")\"\n\nlet private failureOf (property: Value list -> Value) (values: Value list) : exn option =\n    try\n        match property values with\n        | Bool true -> None\n        | Bool false -> Some(LawSpecException(\"PropertyFalse\", \"\") :> exn)\n        | other -> Some(LawSpecException(\"NonBooleanProperty\", sprintf \"%A\" other) :> exn)\n    with\n    | :? LawSpecException as e when e.Code = \"StrategyOutsideRefinement\" || e.Code = \"StrategyDiscards\" -> raise e\n    | e -> Some e\n\n/// Check a property over a generator of its inputs.\nlet check (label: string) (settings: Settings) (gen: Gen<Value list>) (property: Value list -> Value) =\n    let seed = runSeed ()\n    let mutable state = Random.seed seed\n    let mutable passed = 0\n    let mutable failure = None\n    while failure.IsNone && passed < settings.Cases do\n        let size = min 99 passed\n        let mutable drawn = None\n        let mutable discards = 0\n        while drawn.IsNone do\n            let s1, s2 = Random.split state\n            state <- s2\n            match Gen.run gen s1 size with\n            | Some tree -> drawn <- Some tree\n            | None ->\n                discards <- discards + 1\n                if discards > settings.MaxAttempts then\n                    Harness.abort \"CannotSatisfy\"\n                        (sprintf \"%s: no input satisfied the law's domain after %d attempts (seed %O)\" label settings.MaxAttempts seed)\n        let tree = drawn.Value\n        match failureOf property tree.Value with\n        | None -> passed <- passed + 1\n        | Some error -> failure <- Some(tree, error)\n    match failure with\n    | None -> ()\n    | Some(tree, error) ->\n        let mutable best = tree\n        let mutable bestError = error\n        let mutable steps = 0\n        let mutable searching = true\n        while searching && steps < settings.MaxShrinks do\n            let next =\n                best.Children\n                |> Seq.truncate (settings.MaxShrinks * 4)\n                |> Seq.tryPick (fun child -> failureOf property child.Value |> Option.map (fun e -> child, e))\n            match next with\n            | Some(child, e) ->\n                best <- child\n                bestError <- e\n                steps <- steps + 1\n            | None -> searching <- false\n        let message =\n            sprintf \"%s failed after %d passing case(s) and %d shrink(s): counterexample %s; seed %O (LAWSPEC_SEED=%O replays it)\\n%s\"\n                label passed steps (render best.Value) seed seed bestError.Message\n        raise (LawSpecException(\"PropertyFailed\", message, [], bestError))\n\n/// A law's generation settings.\nlet settings (cases: int) (attempts: int) (shrinks: int) = { Cases = cases; MaxAttempts = attempts; MaxShrinks = shrinks }\n\n/// What generation reads: the schema, the case's symbols and the discard budget.\nlet generation (schema: Schema.Schema) (symbols: Scalar.SymbolContext) (attempts: int) : Generators.Context =\n    { Schema = schema; Symbols = symbols; Factories = Map.empty; Attempts = attempts }\n\n/// Each boundary case, in order; the first that fails names its position.\nlet boundaries (label: string) (cases: Value list list) (law: Value list -> Value) =\n    cases\n    |> List.iteri (fun i values ->\n        try\n            match law values with\n            | Bool true -> ()\n            | other -> Fail.raiseWith \"ContractFailed\" (sprintf \"%s boundary %d returned %A\" label i other)\n        with\n        | :? LawSpecException as e ->\n            raise (LawSpecException(\"BoundaryFailed\", sprintf \"%s boundary %d %s: %s\" label i (render values) e.Message, [], e)))\n\n/// A strategy's value must lie inside the input's refinement.\nlet checkDrawn (strategy: string) (input: string) (value: Value) (holds: bool) =\n    if holds then value\n    else Harness.abort \"StrategyOutsideRefinement\" (sprintf \"strategy %s produced %s for %s, outside the input's refinement\" strategy (Recorded.renderPlain value) input)\n\n/// A strategy's draw that keeps only values a predicate accepts.\nlet suchThat (strategy: string) (predicate: Value -> bool) (limit: int) (gen: Gen<Value>) =\n    Gen.suchThat predicate limit (fun () -> Harness.abort \"StrategyDiscards\" (sprintf \"strategy %s discarded %d values\" strategy limit)) gen\n"
